    #[test]
    fn pinned_chart_members_pass_runtime_focus_gate() {
        let runtime = ExcelRuntime::new();
        let document = office_idl::OfficeIdlDocument::from_json_str(super::PINNED_OM_TEMPLATE_JSON)
            .expect("pinned OM template");
        let chart_surfaces = [
            "ChartObjects",
            "ChartObject",
            "Chart",
            "WorksheetFunction",
            "Sheets",
            "Charts",
            "ChartArea",
            "PlotArea",
            "ChartTitle",
            "Legend",
            "DataTable",
            "ChartFormat",
            "Adjustments",
            "FillFormat",
            "GlowFormat",
            "LineFormat",
            "PictureFormat",
            "ShadowFormat",
            "SoftEdgeFormat",
            "TextFrame2",
            "ThreeDFormat",
            "ChartGroups",
            "ChartGroup",
            "CategoryCollection",
            "ChartCategory",
            "SeriesLines",
            "DropLines",
            "HiLoLines",
            "UpBars",
            "DownBars",
            "Axes",
            "Axis",
            "TickLabels",
            "Gridlines",
            "DisplayUnitLabel",
            "AxisTitle",
            "SeriesCollection",
            "Series",
            "LeaderLines",
            "DataLabels",
            "DataLabel",
            "Points",
            "Point",
        ];

        for surface_name in chart_surfaces {
            let interface = document
                .interfaces
                .iter()
                .find(|interface| interface.name == surface_name)
                .unwrap_or_else(|| panic!("{surface_name} pinned interface"));
            for member in &interface.members {
                if matches!(member.support, office_idl::SupportState::Unsupported) {
                    continue;
                }
                runtime
                    .focus_member_supported(surface_name, &member.name, false)
                    .unwrap_or_else(|error| {
                        panic!("{surface_name}.{} read gate failed: {error:?}", member.name)
                    });
                if matches!(
                    member.access,
                    office_idl::AccessMode::Write | office_idl::AccessMode::Readwrite
                ) {
                    runtime
                        .focus_member_supported(surface_name, &member.name, true)
                        .unwrap_or_else(|error| {
                            panic!(
                                "{surface_name}.{} write gate failed: {error:?}",
                                member.name
                            )
                        });
                }
            }
        }
    }

    #[test]
    fn parser_backed_formula_functions_are_pinned_as_worksheet_functions() {
        let source = super::FORMULA_IMPLEMENTATION_SOURCE;
        let parser_start = source
            .find("fn formula_array_projection_function_name")
            .expect("formula function helper start");
        let parser_end = source
            .find("fn parse_formula_reference_text")
            .expect("formula reference parser boundary");
        let parser_source = &source[parser_start..parser_end];
        let marker = "name.eq_ignore_ascii_case(\"";
        let mut parser_names = std::collections::BTreeSet::new();
        let mut offset = 0_usize;
        while let Some(relative_start) = parser_source[offset..].find(marker) {
            let name_start = offset + relative_start + marker.len();
            let Some(relative_end) = parser_source[name_start..].find('"') else {
                break;
            };
            let name = &parser_source[name_start..name_start + relative_end];
            if !matches!(name, "TRUE" | "FALSE") {
                parser_names.insert(name.to_string());
            }
            offset = name_start + relative_end + 1;
        }

        let document = office_idl::OfficeIdlDocument::from_json_str(super::PINNED_OM_TEMPLATE_JSON)
            .expect("pinned OM template");
        let worksheet_function = document
            .interfaces
            .iter()
            .find(|interface| interface.name == "WorksheetFunction")
            .expect("WorksheetFunction interface");
        let pinned_names = worksheet_function
            .members
            .iter()
            .map(|member| member.name.replace('_', ".").to_ascii_uppercase())
            .collect::<std::collections::BTreeSet<_>>();
        let missing = parser_names
            .difference(&pinned_names)
            .cloned()
            .collect::<Vec<_>>();
        assert!(
            missing.is_empty(),
            "parser-backed formula functions missing from WorksheetFunction: {missing:?}"
        );
    }

    #[test]
    fn opens_and_saves_detected_format() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: true,
            })
            .expect("open workbook");

        assert_eq!(
            runtime
                .workbook_model(workbook)
                .expect("model")
                .display_name,
            "Workbook"
        );
        assert_eq!(
            runtime.worksheets(workbook).expect("worksheets")[0].name,
            "Sheet1"
        );
        assert!(runtime.is_read_only(workbook).expect("read_only"));
        assert!(supports_format(FileFormat::Xlsx));

        let bytes = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook");
        let reparsed = OpcPackage::from_bytes(&bytes).expect("reparse saved workbook");
        assert!(reparsed.contains("customXml/item1.xml"));

        runtime.close_workbook(workbook).expect("close workbook");
    }

    #[test]
    fn gets_and_sets_range_values_for_mutable_workbook() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let sheet_id = runtime.worksheets(workbook).expect("worksheets")[0].id;

        let initial = runtime
            .get_range_values(GetRangeValuesSpec {
                workbook,
                range: RangeRef::single_rect(
                    WorkbookId(1),
                    sheet_id,
                    Rect {
                        row_first: 1,
                        row_last: 1,
                        col_first: 1,
                        col_last: 3,
                    },
                ),
            })
            .expect("initial range");
        assert_eq!(initial.values[0], OmValue::Number(42.0));
        assert_eq!(initial.values[1], OmValue::Text("SHARED".to_string()));
        assert_eq!(initial.values[2], OmValue::Text("shared".to_string()));

        runtime
            .set_range_values(SetRangeValuesSpec {
                workbook,
                range: RangeRef::single_rect(
                    WorkbookId(1),
                    sheet_id,
                    Rect {
                        row_first: 2,
                        row_last: 2,
                        col_first: 1,
                        col_last: 2,
                    },
                ),
                values: OmArray::new(
                    1,
                    2,
                    vec![OmValue::Text("changed".to_string()), OmValue::Bool(true)],
                )
                .expect("values"),
            })
            .expect("set range");

        let updated = runtime
            .get_range_values(GetRangeValuesSpec {
                workbook,
                range: RangeRef::single_rect(
                    WorkbookId(1),
                    sheet_id,
                    Rect {
                        row_first: 2,
                        row_last: 2,
                        col_first: 1,
                        col_last: 2,
                    },
                ),
            })
            .expect("updated range");
        assert_eq!(updated.values[0], OmValue::Text("changed".to_string()));
        assert_eq!(updated.values[1], OmValue::Bool(true));

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook");
        let reopened = ExcelRuntime::new()
            .codec
            .load(&saved, office_common::LoadOptions::default())
            .expect("reopen saved workbook");
        let reopened_sheet_id = reopened.state.worksheets[0].id;
        assert_eq!(
            reopened
                .state
                .cell(reopened_sheet_id, 2, 1)
                .expect("A2")
                .value,
            office_common::CellValue::Text("changed".to_string())
        );
        assert_eq!(
            reopened
                .state
                .cell(reopened_sheet_id, 2, 2)
                .expect("B2")
                .value,
            office_common::CellValue::Bool(true)
        );
    }

