    #[test]
    fn workbook_date1904_dispatch_roundtrips_and_marks_workbook_dirty() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");

        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Date1904", &[])
                .expect("Workbook.Date1904 default")
        ));
        let application = runtime.root_application();
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet before Workbook.Date1904"),
        );
        let search_range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1".to_string())])
                .expect("search range before Workbook.Date1904"),
        );
        runtime
            .dispatch_set(
                search_range,
                "Value",
                OmValue::Text("date1904 needle".to_string()),
                &[],
            )
            .expect("seed Range.Find value before Workbook.Date1904");
        runtime
            .dispatch_invoke(search_range, "Copy", &[])
            .expect("Range.Copy before Workbook.Date1904");
        runtime
            .dispatch_invoke(
                search_range,
                "Find",
                &[OmValue::Text("date1904 needle".to_string())],
            )
            .expect("Range.Find before Workbook.Date1904");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(application, "CutCopyMode", &[])
                    .expect("Application.CutCopyMode before Workbook.Date1904")
            ),
            f64::from(super::XL_COPY)
        );

        runtime
            .dispatch_set(workbook.0, "Date1904", OmValue::Bool(true), &[])
            .expect("Workbook.Date1904 = true");
        assert!(expect_bool(
            runtime
                .dispatch_get(workbook.0, "Date1904", &[])
                .expect("Workbook.Date1904 after true")
        ));
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after Date1904")
        ));
        assert!(!expect_bool(
            runtime
                .dispatch_get(application, "CutCopyMode", &[])
                .expect("Application.CutCopyMode after Workbook.Date1904")
        ));
        assert_eq!(
            runtime
                .dispatch_invoke(search_range, "FindNext", &[])
                .expect_err("Range.FindNext should require a new Find after Workbook.Date1904")
                .code,
            OmErrorCode::InvalidState
        );

        runtime
            .dispatch_set(workbook.0, "Date1904", OmValue::Bool(false), &[])
            .expect("Workbook.Date1904 = false");
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Date1904", &[])
                .expect("Workbook.Date1904 after false")
        ));

        assert_eq!(
            runtime
                .dispatch_set(workbook.0, "Date1904", OmValue::Number(1.0), &[])
                .expect_err("Workbook.Date1904 should reject numeric values")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_get(workbook.0, "Date1904", &[OmValue::Number(1.0)])
                .expect_err("Workbook.Date1904 should reject index args")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_set(
                    workbook.0,
                    "Date1904",
                    OmValue::Bool(true),
                    &[OmValue::Number(1.0)]
                )
                .expect_err("Workbook.Date1904 set should reject index args")
                .code,
            OmErrorCode::InvalidArgument
        );

        let read_only_workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: true,
            })
            .expect("open read-only workbook");
        assert_eq!(
            runtime
                .dispatch_set(read_only_workbook.0, "Date1904", OmValue::Bool(true), &[])
                .expect_err("Workbook.Date1904 should reject read-only edits")
                .code,
            OmErrorCode::InvalidState
        );
    }

