    #[test]
    fn worksheet_names_are_sheet_scoped() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime.create_workbook().expect("workbook");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("Application.ActiveSheet"),
        );
        let workbook_names = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Names", &[])
                .expect("Workbook.Names"),
        );
        let worksheet_names = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "Names", &[])
                .expect("Worksheet.Names"),
        );

        let local_name = expect_object_handle(
            runtime
                .dispatch_invoke(
                    worksheet_names,
                    "Add",
                    &[
                        OmValue::Text("LocalTotal".to_string()),
                        OmValue::Text("=Sheet1!$B$2".to_string()),
                    ],
                )
                .expect("Worksheet.Names.Add"),
        );
        let local_parent = expect_object_handle(
            runtime
                .dispatch_get(local_name, "Parent", &[])
                .expect("worksheet Name.Parent"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(local_parent, "Name", &[])
                    .expect("worksheet Name.Parent.Name")
            ),
            "Sheet1"
        );

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(workbook_names, "Count", &[])
                    .expect("Workbook.Names.Count")
            ),
            0.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(worksheet_names, "Count", &[])
                    .expect("Worksheet.Names.Count")
            ),
            1.0
        );
        assert!(
            runtime
                .dispatch_get(
                    workbook_names,
                    "Item",
                    &[OmValue::Text("LocalTotal".to_string())],
                )
                .is_err()
        );
        assert!(
            runtime
                .dispatch_get(
                    worksheet_names,
                    "Item",
                    &[OmValue::Text("localtotal".to_string())],
                )
                .is_ok()
        );
    }

    #[test]
    fn collection_properties_accept_direct_index_args() {
        let mut runtime = ExcelRuntime::new();
        let workbook1 = runtime.create_workbook().expect("create workbook1");
        let workbook2 = runtime.create_workbook().expect("create workbook2");
        let worksheets1 = expect_object_handle(
            runtime
                .dispatch_get(workbook1.0, "Worksheets", &[])
                .expect("Workbook1.Worksheets"),
        );
        let worksheet1 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets1, "Item", &[OmValue::Number(1.0)])
                .expect("Workbook1.Worksheets.Item(1)"),
        );

        runtime
            .dispatch_set(
                worksheet1,
                "Name",
                OmValue::Text("Renamed".to_string()),
                &[],
            )
            .expect("rename workbook1 sheet");

        let application = runtime.root_application();
        runtime
            .dispatch_invoke(workbook1.0, "Activate", &[])
            .expect("activate workbook1");
        let first_workbook = expect_object_handle(
            runtime
                .dispatch_get(application, "Workbooks", &[OmValue::Number(1.0)])
                .expect("Application.Workbooks(1)"),
        );
        let named_workbook = expect_object_handle(
            runtime
                .dispatch_get(
                    application,
                    "Workbooks",
                    &[OmValue::Text("Book2".to_string())],
                )
                .expect("Application.Workbooks(\"Book2\")"),
        );
        let indexed_worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook1.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook1.Worksheets(1)"),
        );
        let named_worksheet = expect_object_handle(
            runtime
                .dispatch_get(
                    workbook1.0,
                    "Worksheets",
                    &[OmValue::Text("Renamed".to_string())],
                )
                .expect("Workbook1.Worksheets(\"Renamed\")"),
        );
        let application_sheets_worksheet = expect_object_handle(
            runtime
                .dispatch_get(
                    application,
                    "Sheets",
                    &[OmValue::Text("Renamed".to_string())],
                )
                .expect("Application.Sheets(\"Renamed\")"),
        );
        let workbook_sheets_worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook1.0, "Sheets", &[OmValue::Number(1.0)])
                .expect("Workbook1.Sheets(1)"),
        );

        assert_eq!(first_workbook, workbook1.0);
        assert_eq!(named_workbook, workbook2.0);
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(first_workbook, "Name", &[])
                    .expect("Application.Workbooks(1).Name")
            ),
            "Book1"
        );
        assert_eq!(
            expect_object_handle(
                runtime
                    .dispatch_get(indexed_worksheet, "Parent", &[])
                    .expect("Workbook1.Worksheets(1).Parent")
            ),
            workbook1.0
        );
        assert_eq!(
            expect_object_handle(
                runtime
                    .dispatch_get(named_worksheet, "Parent", &[])
                    .expect("Workbook1.Worksheets(\"Renamed\").Parent")
            ),
            workbook1.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(indexed_worksheet, "Name", &[])
                    .expect("Workbook1.Worksheets(1).Name")
            ),
            "Renamed"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(named_worksheet, "Name", &[])
                    .expect("Workbook1.Worksheets(\"Renamed\").Name")
            ),
            "Renamed"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(application_sheets_worksheet, "Name", &[])
                    .expect("Application.Sheets(\"Renamed\").Name")
            ),
            "Renamed"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(workbook_sheets_worksheet, "Name", &[])
                    .expect("Workbook1.Sheets(1).Name")
            ),
            "Renamed"
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "Workbooks", &[OmValue::Bool(true)])
                .expect_err("Application.Workbooks(true) should be rejected")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_get(
                    workbook1.0,
                    "Worksheets",
                    &[OmValue::Text("Missing".to_string())]
                )
                .expect_err("Workbook1.Worksheets(\"Missing\") should fail")
                .code,
            OmErrorCode::NotFound
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "Sheets", &[OmValue::Bool(true)])
                .expect_err("Application.Sheets(true) should be rejected")
                .code,
            OmErrorCode::TypeMismatch
        );
    }

    #[test]
    fn application_calculate_full_rebuild_preserves_selection() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let selection_before = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection before rebuild"),
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(application, "CalculateFullRebuild", &[])
                .expect("Application.CalculateFullRebuild"),
            OmValue::Empty
        ));

        let selection_after = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after rebuild"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection_before, "Address", &[])
                    .expect("Selection before rebuild address")
            ),
            expect_text(
                runtime
                    .dispatch_get(selection_after, "Address", &[])
                    .expect("Selection after rebuild address")
            )
        );
        assert_eq!(
            runtime
                .dispatch_invoke(application, "CalculateFullRebuild", &[OmValue::Bool(true)],)
                .expect_err("CalculateFullRebuild arguments should be rejected")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

