    #[test]
    fn application_calculate_updates_scalar_matrix_and_percent_formulas() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let matrix = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B1:C2".to_string())])
                .expect("Range(B1:C2)"),
        );
        let percent_values = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("D1:D4".to_string())])
                .expect("Range(D1:D4)"),
        );
        let zero_values = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("E1:E2".to_string())])
                .expect("Range(E1:E2)"),
        );
        let text_matrix = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("G1:H2".to_string())])
                .expect("Range(G1:H2)"),
        );
        let formulas = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("J1:J11".to_string())],
                )
                .expect("Range(J1:J11)"),
        );

        runtime
            .dispatch_set(
                matrix,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        2,
                        2,
                        vec![
                            OmValue::Number(1.0),
                            OmValue::Number(2.0),
                            OmValue::Number(3.0),
                            OmValue::Number(4.0),
                        ],
                    )
                    .expect("matrix values"),
                ),
                &[],
            )
            .expect("set matrix values");
        runtime
            .dispatch_set(
                percent_values,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        4,
                        1,
                        vec![
                            OmValue::Number(10.0),
                            OmValue::Number(20.0),
                            OmValue::Number(30.0),
                            OmValue::Number(40.0),
                        ],
                    )
                    .expect("percent values"),
                ),
                &[],
            )
            .expect("set percent values");
        runtime
            .dispatch_set(
                zero_values,
                "Value2",
                OmValue::Array(
                    OmArray::new(2, 1, vec![OmValue::Number(0.0), OmValue::Number(0.0)])
                        .expect("zero values"),
                ),
                &[],
            )
            .expect("set zero values");
        runtime
            .dispatch_set(
                text_matrix,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        2,
                        2,
                        vec![
                            OmValue::Number(1.0),
                            OmValue::Text("bad".to_string()),
                            OmValue::Number(3.0),
                            OmValue::Number(4.0),
                        ],
                    )
                    .expect("text matrix values"),
                ),
                &[],
            )
            .expect("set text matrix values");
        runtime
            .dispatch_set(
                formulas,
                "Formula",
                OmValue::Array(
                    OmArray::new(
                        11,
                        1,
                        vec![
                            OmValue::Text("=MDETERM(B1:C2)".to_string()),
                            OmValue::Text("=MINVERSE(B1:C2)".to_string()),
                            OmValue::Text("=MMULT(B1:C2,B1:C2)".to_string()),
                            OmValue::Text("=MUNIT(3)".to_string()),
                            OmValue::Text("=FREQUENCY(D1:D4,25)".to_string()),
                            OmValue::Text("=PERCENTOF(D1:D2,D1:D4)".to_string()),
                            OmValue::Text("=PERCENTOF(5,D1:D4)".to_string()),
                            OmValue::Text("=PERCENTOF(D1:D2,E1:E2)".to_string()),
                            OmValue::Text("=MDETERM(B1:C3)".to_string()),
                            OmValue::Text("=MDETERM(G1:H2)".to_string()),
                            OmValue::Text("=MINVERSE(E1:E2)".to_string()),
                        ],
                    )
                    .expect("scalar matrix formulas"),
                ),
                &[],
            )
            .expect("set scalar matrix formulas");

        runtime
            .dispatch_invoke(runtime.root_application(), "Calculate", &[])
            .expect("Application.Calculate");

        let values = runtime
            .dispatch_get(formulas, "Value2", &[])
            .expect("scalar matrix values after Calculate");
        let OmValue::Array(values) = values else {
            panic!("expected scalar matrix value array");
        };
        let expected_numbers = [-2.0, -2.0, 7.0, 1.0, 2.0, 0.3, 0.05];
        for (index, expected) in expected_numbers.into_iter().enumerate() {
            let number = expect_number(values.values[index].clone());
            assert!(
                (number - expected).abs() < 1e-10,
                "scalar matrix result {} expected {expected}, got {number}",
                index + 1
            );
        }
        assert_eq!(
            &values.values[7..],
            &[
                OmValue::Error(CellError::Div0),
                OmValue::Error(CellError::Value),
                OmValue::Error(CellError::Value),
                OmValue::Error(CellError::Value),
            ]
        );
    }

