    #[test]
    fn application_calculate_updates_regex_formulas() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let formulas = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("A1:A15".to_string())],
                )
                .expect("Range(A1:A15)"),
        );

        runtime
            .dispatch_set(
                formulas,
                "Formula",
                OmValue::Array(
                    OmArray::new(
                        15,
                        1,
                        vec![
                            OmValue::Text(r#"=REGEXTEST("Order-42","[0-9]+")"#.to_string()),
                            OmValue::Text(r#"=REGEXTEST("Order-42","^[a-z]+")"#.to_string()),
                            OmValue::Text(r#"=REGEXTEST("Order-42","^[a-z]+",1)"#.to_string()),
                            OmValue::Text(
                                r#"=REGEXEXTRACT("Order-42-ABC","[0-9]+")"#.to_string(),
                            ),
                            OmValue::Text(
                                r#"=REGEXEXTRACT("Order-42-ABC","([A-Za-z]+)-([0-9]+)",2)"#
                                    .to_string(),
                            ),
                            OmValue::Text(
                                r#"=REGEXEXTRACT("Order-42-ABC","[a-z]+",0,1)"#.to_string(),
                            ),
                            OmValue::Text(
                                r##"=REGEXREPLACE("A12 B34","[0-9]+","#")"##.to_string(),
                            ),
                            OmValue::Text(
                                r##"=REGEXREPLACE("A12 B34 C56","[0-9]+","#",2)"##.to_string(),
                            ),
                            OmValue::Text(
                                r##"=REGEXREPLACE("A12 B34 C56","[0-9]+","#",-1)"##.to_string(),
                            ),
                            OmValue::Text(
                                r#"=REGEXREPLACE("abc","[A-Z]+","x",0,1)"#.to_string(),
                            ),
                            OmValue::Text(
                                r#"=REGEXREPLACE("2026-05-05","([0-9]{4})-([0-9]{2})-([0-9]{2})","$2/$3/$1")"#.to_string(),
                            ),
                            OmValue::Text(r#"=REGEXTEST("abc","[")"#.to_string()),
                            OmValue::Text(r#"=REGEXEXTRACT("abc","[0-9]+")"#.to_string()),
                            OmValue::Text(r#"=REGEXTEST("abc","abc",2)"#.to_string()),
                            OmValue::Text(r#"=REGEXEXTRACT("abc","abc",3)"#.to_string()),
                        ],
                    )
                    .expect("regex formulas"),
                ),
                &[],
            )
            .expect("set regex formulas");

        runtime
            .dispatch_invoke(runtime.root_application(), "Calculate", &[])
            .expect("Application.Calculate");

        let values = runtime
            .dispatch_get(formulas, "Value2", &[])
            .expect("regex values after Calculate");
        let OmValue::Array(values) = values else {
            panic!("expected regex value array");
        };
        assert_eq!(
            values.values,
            vec![
                OmValue::Number(1.0),
                OmValue::Number(0.0),
                OmValue::Number(1.0),
                OmValue::Text("42".to_string()),
                OmValue::Text("Order".to_string()),
                OmValue::Text("Order".to_string()),
                OmValue::Text("A# B#".to_string()),
                OmValue::Text("A12 B# C56".to_string()),
                OmValue::Text("A12 B34 C#".to_string()),
                OmValue::Text("x".to_string()),
                OmValue::Text("05/05/2026".to_string()),
                OmValue::Error(CellError::Value),
                OmValue::Error(CellError::NA),
                OmValue::Error(CellError::Value),
                OmValue::Error(CellError::Value),
            ]
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    runtime.root_application(),
                    "Evaluate",
                    &[OmValue::Text(
                        r#"=REGEXEXTRACT("abc123","[0-9]+")"#.to_string()
                    )],
                )
                .expect("Application.Evaluate REGEXEXTRACT"),
            OmValue::Text("123".to_string())
        );
    }

    #[test]
    fn application_calculate_updates_xml_language_image_text_formulas() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let formulas = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("A1:A12".to_string())],
                )
                .expect("Range(A1:A12)"),
        );

        runtime
            .dispatch_set(
                formulas,
                "Formula",
                OmValue::Array(
                    OmArray::new(
                        12,
                        1,
                        vec![
                            OmValue::Text(r#"=DETECTLANGUAGE("hello world")"#.to_string()),
                            OmValue::Text(r#"=DETECTLANGUAGE("123")"#.to_string()),
                            OmValue::Text(r#"=TRANSLATE("hello","en","es")"#.to_string()),
                            OmValue::Text(r#"=TRANSLATE("hola","es","en")"#.to_string()),
                            OmValue::Text(r#"=TRANSLATE("custom","en","es")"#.to_string()),
                            OmValue::Text(
                                r#"=IMAGE("https://example.test/a.png","Chart alt")"#.to_string(),
                            ),
                            OmValue::Text(r#"=IMAGE("https://example.test/a.png")"#.to_string()),
                            OmValue::Text(
                                r#"=FILTERXML("<root><item id=""a"">One</item><item>Two</item></root>","//item")"#.to_string(),
                            ),
                            OmValue::Text(
                                r#"=FILTERXML("<root><item id=""a"">One</item></root>","//item/@id")"#.to_string(),
                            ),
                            OmValue::Text(
                                r#"=FILTERXML(WEBSERVICE("data:,<root><item>Data</item></root>"),"//item")"#.to_string(),
                            ),
                            OmValue::Text(r#"=WEBSERVICE("data:,hello%20world")"#.to_string()),
                            OmValue::Text(r#"=FILTERXML("<root>","//item")"#.to_string()),
                        ],
                    )
                    .expect("xml language image formulas"),
                ),
                &[],
            )
            .expect("set xml language image formulas");

        runtime
            .dispatch_invoke(runtime.root_application(), "Calculate", &[])
            .expect("Application.Calculate");

        let values = runtime
            .dispatch_get(formulas, "Value2", &[])
            .expect("xml language image values after Calculate");
        let OmValue::Array(values) = values else {
            panic!("expected xml language image value array");
        };
        assert_eq!(
            values.values,
            vec![
                OmValue::Text("en".to_string()),
                OmValue::Text("und".to_string()),
                OmValue::Text("hola".to_string()),
                OmValue::Text("hello".to_string()),
                OmValue::Text("custom".to_string()),
                OmValue::Text("Chart alt".to_string()),
                OmValue::Text("https://example.test/a.png".to_string()),
                OmValue::Text("One".to_string()),
                OmValue::Text("a".to_string()),
                OmValue::Text("Data".to_string()),
                OmValue::Text("hello world".to_string()),
                OmValue::Error(CellError::Value),
            ]
        );
    }

    #[test]
    fn application_evaluate_calculates_expression_against_active_sheet() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let source = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:A2".to_string())])
                .expect("Range(A1:A2)"),
        );

        runtime
            .dispatch_set(
                source,
                "Value2",
                OmValue::Array(
                    OmArray::new(2, 1, vec![OmValue::Number(4.0), OmValue::Number(6.0)])
                        .expect("source values"),
                ),
                &[],
            )
            .expect("set evaluate source values");

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_invoke(
                        application,
                        "Evaluate",
                        &[OmValue::Text("=SUM(A1:A2)+POWER(2, 3)".to_string())],
                    )
                    .expect("Application.Evaluate"),
            ),
            18.0
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    application,
                    "Evaluate",
                    &[OmValue::Text("SQRT(-1)".to_string())],
                )
                .expect("Application.Evaluate error value"),
            OmValue::Error(CellError::Num)
        );
        assert_eq!(
            runtime
                .dispatch_invoke(application, "Evaluate", &[])
                .expect_err("Application.Evaluate should require one argument")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(application, "Evaluate", &[OmValue::Number(1.0)])
                .expect_err("Application.Evaluate should reject non-text arguments")
                .code,
            OmErrorCode::TypeMismatch
        );
    }

