    #[test]
    fn application_calculate_full_is_noop_and_preserves_selection_and_saved_state() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_calc_chain_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open calc chain workbook");
        let application = runtime.root_application();
        let selection_before = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection before CalculateFull"),
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(application, "CalculateFull", &[])
                .expect("Application.CalculateFull"),
            OmValue::Empty
        ));

        let selection_after = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after CalculateFull"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection_before, "Address", &[])
                    .expect("Selection before CalculateFull address")
            ),
            expect_text(
                runtime
                    .dispatch_get(selection_after, "Address", &[])
                    .expect("Selection after CalculateFull address")
            )
        );
        assert!(expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after Application.CalculateFull")
        ));
        assert_eq!(
            runtime
                .dispatch_invoke(application, "CalculateFull", &[OmValue::Missing])
                .expect_err("Application.CalculateFull args should be rejected")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn application_calculate_full_rebuild_invalidates_calc_chain_artifacts() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_calc_chain_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open calc chain workbook");
        let application = runtime.root_application();

        assert!(matches!(
            runtime
                .dispatch_invoke(application, "CalculateFullRebuild", &[])
                .expect("Application.CalculateFullRebuild"),
            OmValue::Empty
        ));
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after CalculateFullRebuild")
        ));

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save rebuilt workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved rebuilt package");
        let workbook_rels_xml = String::from_utf8(
            saved_package
                .part("xl/_rels/workbook.xml.rels")
                .expect("saved workbook rels")
                .bytes
                .clone(),
        )
        .expect("workbook rels utf8");
        let content_types_xml = String::from_utf8(
            saved_package
                .part("[Content_Types].xml")
                .expect("saved content types")
                .bytes
                .clone(),
        )
        .expect("content types utf8");
        let reopened = ExcelRuntime::new()
            .codec
            .load(&saved, LoadOptions::default())
            .expect("reopen rebuilt workbook");

        assert!(!saved_package.contains("xl/calcChain.xml"));
        assert!(!workbook_rels_xml.contains("calcChain"));
        assert!(!content_types_xml.contains("/xl/calcChain.xml"));
        assert!(reopened.support_parts.calc_chain_part_uri.is_none());
        assert!(reopened.support_parts.calc_chain_relationship.is_none());
    }

    #[test]
    fn application_displayalerts_dispatch_roundtrips_and_rejects_invalid_values() {
        let mut runtime = ExcelRuntime::new();
        let application = runtime.root_application();

        assert!(expect_bool(
            runtime
                .dispatch_get(application, "DisplayAlerts", &[])
                .expect("Application.DisplayAlerts default")
        ));

        runtime
            .dispatch_set(application, "DisplayAlerts", OmValue::Bool(false), &[])
            .expect("Application.DisplayAlerts = false");
        assert!(!expect_bool(
            runtime
                .dispatch_get(application, "DisplayAlerts", &[])
                .expect("Application.DisplayAlerts after false")
        ));

        runtime
            .dispatch_set(application, "DisplayAlerts", OmValue::Bool(true), &[])
            .expect("Application.DisplayAlerts = true");
        assert!(expect_bool(
            runtime
                .dispatch_get(application, "DisplayAlerts", &[])
                .expect("Application.DisplayAlerts after true")
        ));

        assert_eq!(
            runtime
                .dispatch_set(
                    application,
                    "DisplayAlerts",
                    OmValue::Text("bad".to_string()),
                    &[]
                )
                .expect_err("Application.DisplayAlerts should reject non-bool values")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "DisplayAlerts", &[OmValue::Bool(true)])
                .expect_err("Application.DisplayAlerts should reject index args")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_set(
                    application,
                    "DisplayAlerts",
                    OmValue::Bool(true),
                    &[OmValue::Bool(true)],
                )
                .expect_err("Application.DisplayAlerts set should reject index args")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn application_status_bar_dispatch_roundtrips_and_resets_with_false() {
        let mut runtime = ExcelRuntime::new();
        let application = runtime.root_application();

        assert!(!expect_bool(
            runtime
                .dispatch_get(application, "StatusBar", &[])
                .expect("Application.StatusBar default")
        ));

        runtime
            .dispatch_set(
                application,
                "StatusBar",
                OmValue::Text("Calculating workbook".to_string()),
                &[],
            )
            .expect("Application.StatusBar text");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(application, "StatusBar", &[])
                    .expect("Application.StatusBar after text")
            ),
            "Calculating workbook"
        );

        runtime
            .dispatch_set(application, "StatusBar", OmValue::Bool(false), &[])
            .expect("Application.StatusBar false reset");
        assert!(!expect_bool(
            runtime
                .dispatch_get(application, "StatusBar", &[])
                .expect("Application.StatusBar after reset")
        ));

        assert_eq!(
            runtime
                .dispatch_set(application, "StatusBar", OmValue::Bool(true), &[])
                .expect_err("Application.StatusBar should reject true")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_set(application, "StatusBar", OmValue::Number(1.0), &[])
                .expect_err("Application.StatusBar should reject numeric values")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "StatusBar", &[OmValue::Bool(true)])
                .expect_err("Application.StatusBar should reject index args")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

