    #[test]
    fn range_multi_area_clear_methods_apply_each_area() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let clear_formats_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("E2,F3:G3".to_string())],
                )
                .expect("Range(E2,F3:G3)"),
        );
        let clear_contents_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("H2,I3:J3".to_string())],
                )
                .expect("Range(H2,I3:J3)"),
        );
        let clear_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("K2,L3:M3".to_string())],
                )
                .expect("Range(K2,L3:M3)"),
        );
        runtime
            .dispatch_set(
                clear_formats_range,
                "Value2",
                OmValue::Text("kept".to_string()),
                &[],
            )
            .expect("seed clear-format values");
        runtime
            .dispatch_set(
                clear_contents_range,
                "Formula",
                OmValue::Text("=ROW()".to_string()),
                &[],
            )
            .expect("seed clear-contents formulas");
        runtime
            .dispatch_set(
                clear_range,
                "Value2",
                OmValue::Text("removed".to_string()),
                &[],
            )
            .expect("seed clear values");
        let sheet_id = runtime
            .runtime_workbook(workbook)
            .expect("runtime workbook")
            .loaded
            .state
            .worksheets
            .first()
            .expect("worksheet")
            .id;
        {
            let worksheet = runtime
                .runtime_workbook_mut(workbook)
                .expect("runtime workbook mut")
                .loaded
                .state
                .worksheet_data_for_sheet_mut(sheet_id)
                .expect("worksheet data");
            for key in [
                (2, 5),
                (3, 6),
                (3, 7),
                (2, 8),
                (3, 9),
                (3, 10),
                (2, 11),
                (3, 12),
                (3, 13),
            ] {
                worksheet.cells.get_mut(&key).expect("seeded cell").style_id = Some(StyleId(0));
            }
        }
        runtime
            .dispatch_set(workbook.0, "Saved", OmValue::Bool(true), &[])
            .expect("reset Workbook.Saved before multi-area clear");

        assert_eq!(
            runtime
                .dispatch_invoke(clear_formats_range, "ClearFormats", &[])
                .expect("multi-area ClearFormats"),
            OmValue::Empty
        );
        for address in ["E2", "F3", "G3"] {
            let cell = expect_object_handle(
                runtime
                    .dispatch_invoke(active_sheet, "Range", &[OmValue::Text(address.to_string())])
                    .expect("cell range after multi-area ClearFormats"),
            );
            assert_eq!(
                expect_text(
                    runtime
                        .dispatch_get(cell, "Value2", &[])
                        .expect("cell Value2 after multi-area ClearFormats")
                ),
                "kept"
            );
        }
        {
            let worksheet = runtime
                .runtime_workbook(workbook)
                .expect("runtime workbook after ClearFormats")
                .loaded
                .state
                .worksheet_data_for_sheet(sheet_id)
                .expect("worksheet data after ClearFormats");
            for key in [(2, 5), (3, 6), (3, 7)] {
                assert_eq!(
                    worksheet
                        .cells
                        .get(&key)
                        .expect("format-cleared cell")
                        .style_id,
                    None
                );
            }
        }

        assert_eq!(
            runtime
                .dispatch_invoke(clear_contents_range, "ClearContents", &[])
                .expect("multi-area ClearContents"),
            OmValue::Empty
        );
        for address in ["H2", "I3", "J3"] {
            let cell = expect_object_handle(
                runtime
                    .dispatch_invoke(active_sheet, "Range", &[OmValue::Text(address.to_string())])
                    .expect("cell range after multi-area ClearContents"),
            );
            assert_eq!(
                runtime
                    .dispatch_get(cell, "Formula", &[])
                    .expect("cell Formula after multi-area ClearContents"),
                OmValue::Empty
            );
        }
        {
            let worksheet = runtime
                .runtime_workbook(workbook)
                .expect("runtime workbook after ClearContents")
                .loaded
                .state
                .worksheet_data_for_sheet(sheet_id)
                .expect("worksheet data after ClearContents");
            for key in [(2, 8), (3, 9), (3, 10)] {
                assert_eq!(
                    worksheet
                        .cells
                        .get(&key)
                        .expect("contents-cleared style shell")
                        .style_id,
                    Some(StyleId(0))
                );
            }
        }

        assert_eq!(
            runtime
                .dispatch_invoke(clear_range, "Clear", &[])
                .expect("multi-area Clear"),
            OmValue::Empty
        );
        {
            let worksheet = runtime
                .runtime_workbook(workbook)
                .expect("runtime workbook after Clear")
                .loaded
                .state
                .worksheet_data_for_sheet(sheet_id)
                .expect("worksheet data after Clear");
            for key in [(2, 11), (3, 12), (3, 13)] {
                assert!(
                    worksheet.cells.get(&key).is_none(),
                    "Range.Clear should remove multi-area cell {key:?}"
                );
            }
        }
        assert_eq!(
            runtime
                .dispatch_invoke(clear_range, "Clear", &[OmValue::Bool(true)])
                .expect_err("multi-area Clear rejects arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after multi-area clear")
        ));
    }

    #[test]
    fn range_dispatch_rows_and_columns_project_count_over_same_rect() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B2".to_string())])
                .expect("Range(A1:B2)"),
        );
        let rows = expect_object_handle(
            runtime
                .dispatch_get(range, "Rows", &[])
                .expect("Range.Rows"),
        );
        let columns = expect_object_handle(
            runtime
                .dispatch_get(range, "Columns", &[])
                .expect("Range.Columns"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(rows, "Address", &[])
                    .expect("Rows.Address")
            ),
            "$A$1:$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(columns, "Address", &[])
                    .expect("Columns.Address")
            ),
            "$A$1:$B$2"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(range, "Count", &[])
                    .expect("Range.Count")
            ),
            4.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(rows, "Count", &[])
                    .expect("Rows.Count")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(columns, "Count", &[])
                    .expect("Columns.Count")
            ),
            2.0
        );
        let rows_columns = expect_object_handle(
            runtime
                .dispatch_get(rows, "Columns", &[])
                .expect("Rows.Columns"),
        );
        let columns_rows = expect_object_handle(
            runtime
                .dispatch_get(columns, "Rows", &[])
                .expect("Columns.Rows"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(rows_columns, "Count", &[])
                    .expect("Rows.Columns.Count")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(columns_rows, "Count", &[])
                    .expect("Columns.Rows.Count")
            ),
            2.0
        );
        let rows_parent = expect_object_handle(
            runtime
                .dispatch_get(rows, "Parent", &[])
                .expect("Rows.Parent"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(rows_parent, "Name", &[])
                    .expect("Rows.Parent.Name")
            ),
            expect_text(
                runtime
                    .dispatch_get(active_sheet, "Name", &[])
                    .expect("ActiveSheet.Name")
            )
        );
    }

