    #[test]
    fn range_dispatch_scalar_value2_broadcasts_over_multi_cell_rect() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let sheet_id = runtime.worksheets(workbook).expect("worksheets")[0].id;
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B2".to_string())])
                .expect("Range(A1:B2)"),
        );

        runtime
            .dispatch_set(range, "Value2", OmValue::Text("fill".to_string()), &[])
            .expect("set scalar Value2");

        let OmValue::Array(array) = runtime
            .dispatch_get(range, "Value2", &[])
            .expect("get scalar-broadcast array")
        else {
            panic!("expected OmValue::Array");
        };

        assert_eq!(array.rows, 2);
        assert_eq!(array.cols, 2);
        assert_eq!(array.values, vec![OmValue::Text("fill".to_string()); 4]);

        let updated = runtime
            .get_range_values(GetRangeValuesSpec {
                workbook,
                range: RangeRef::single_rect(
                    WorkbookId(1),
                    sheet_id,
                    Rect {
                        row_first: 1,
                        row_last: 2,
                        col_first: 1,
                        col_last: 2,
                    },
                ),
            })
            .expect("updated range");
        assert_eq!(updated.values, array.values);
    }

    #[test]
    fn worksheet_dispatch_rejects_invalid_range_and_cells_arguments() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );

        let invalid_range = runtime.dispatch_invoke(
            active_sheet,
            "Range",
            &[OmValue::Text("A1:B2:C3".to_string())],
        );
        assert_eq!(
            invalid_range.expect_err("invalid range should fail").code,
            OmErrorCode::Parse
        );
        let mixed_axis_range =
            runtime.dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A:1".to_string())]);
        assert_eq!(
            mixed_axis_range
                .expect_err("mixed row/column range should fail")
                .code,
            OmErrorCode::Parse
        );

        let invalid_cells_type = runtime.dispatch_invoke(
            active_sheet,
            "Cells",
            &[OmValue::Text("1".to_string()), OmValue::Number(1.0)],
        );
        assert_eq!(
            invalid_cells_type
                .expect_err("non-numeric Cells row should fail")
                .code,
            OmErrorCode::TypeMismatch
        );

        let invalid_cells_index = runtime.dispatch_invoke(
            active_sheet,
            "Cells",
            &[OmValue::Number(0.0), OmValue::Number(1.0)],
        );
        assert_eq!(
            invalid_cells_index
                .expect_err("zero-based Cells row should fail")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn worksheet_range_and_cells_dispatch_round_trip_value2_and_address() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );

        let range_a1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Range(A1)"),
        );
        let cell_a1 = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Cells",
                    &[OmValue::Number(1.0), OmValue::Number(1.0)],
                )
                .expect("Cells(1, 1)"),
        );
        let whole_columns = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B:D".to_string())])
                .expect("Range(B:D)"),
        );
        let whole_rows = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("2:4".to_string())])
                .expect("Range(2:4)"),
        );
        let application_whole_column = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Range", &[OmValue::Text("A:A".to_string())])
                .expect("Application.Range(A:A)"),
        );

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(range_a1, "Value2", &[])
                    .expect("A1 Value2")
            ),
            42.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(range_a1, "Address", &[])
                    .expect("A1 Address")
            ),
            "$A$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(cell_a1, "Address", &[])
                    .expect("Cells(1, 1) Address")
            ),
            "$A$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(whole_columns, "Address", &[])
                    .expect("Range(B:D) Address")
            ),
            "$B:$D"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        whole_columns,
                        "Address",
                        &[
                            OmValue::Missing,
                            OmValue::Missing,
                            OmValue::Number(XL_R1C1 as f64)
                        ],
                    )
                    .expect("Range(B:D) R1C1 Address")
            ),
            "C2:C4"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(whole_rows, "Address", &[])
                    .expect("Range(2:4) Address")
            ),
            "$2:$4"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(
                        whole_rows,
                        "Address",
                        &[
                            OmValue::Missing,
                            OmValue::Missing,
                            OmValue::Number(XL_R1C1 as f64)
                        ],
                    )
                    .expect("Range(2:4) R1C1 Address")
            ),
            "R2:R4"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(application_whole_column, "Address", &[])
                    .expect("Application.Range(A:A) Address")
            ),
            "$A:$A"
        );

        runtime
            .dispatch_set(
                range_a1,
                "Value2",
                OmValue::Text("dispatch-edited".to_string()),
                &[],
            )
            .expect("set A1 Value2");

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(range_a1, "Value2", &[])
                    .expect("edited A1 Value2")
            ),
            "dispatch-edited"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(cell_a1, "Value2", &[])
                    .expect("Cells(1, 1) Value2")
            ),
            "dispatch-edited"
        );
    }

    #[test]
    fn worksheet_range_dispatch_accepts_range_handles_and_mixed_variant_endpoints() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let active_workbook = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveWorkbook", &[])
                .expect("ActiveWorkbook"),
        );
        let cell_a1 = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Cells",
                    &[OmValue::Number(1.0), OmValue::Number(1.0)],
                )
                .expect("Cells(1, 1)"),
        );
        let cell_b2 = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Cells",
                    &[OmValue::Number(2.0), OmValue::Number(2.0)],
                )
                .expect("Cells(2, 2)"),
        );
        let header_range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B1".to_string())])
                .expect("Range(A1:B1)"),
        );
        let multi_area_source = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("A1:A2,C1:C2".to_string())],
                )
                .expect("Range(A1:A2,C1:C2)"),
        );
        let multi_area_object_range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Object(multi_area_source)])
                .expect("Range(multi_area_source)"),
        );
        let multi_area_object_areas = expect_object_handle(
            runtime
                .dispatch_get(multi_area_object_range, "Areas", &[])
                .expect("Range(multi_area_source).Areas"),
        );
        let selection_after_multi_area_object = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after Range(multi_area_source)"),
        );
        let object_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Object(cell_b2), OmValue::Object(cell_a1)],
                )
                .expect("Range(cell_b2, cell_a1)"),
        );
        let single_object_range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Object(header_range)])
                .expect("Range(header_range)"),
        );
        let mixed_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Object(header_range), OmValue::Object(cell_b2)],
                )
                .expect("Range(header_range, cell_b2)"),
        );
        let text_object_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("A1".to_string()), OmValue::Object(cell_b2)],
                )
                .expect("Range(\"A1\", cell_b2)"),
        );
        let second_workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open second workbook");
        let foreign_worksheets = expect_object_handle(
            runtime
                .dispatch_get(second_workbook.0, "Worksheets", &[])
                .expect("second workbook worksheets"),
        );
        let foreign_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(foreign_worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("second workbook worksheet"),
        );
        let foreign_cell = expect_object_handle(
            runtime
                .dispatch_invoke(
                    foreign_sheet,
                    "Cells",
                    &[OmValue::Number(1.0), OmValue::Number(1.0)],
                )
                .expect("foreign Cells(1, 1)"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(object_range, "Address", &[])
                    .expect("object_range Address")
            ),
            "$A$1:$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(single_object_range, "Address", &[])
                    .expect("single_object_range Address")
            ),
            "$A$1:$B$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(multi_area_object_range, "Address", &[])
                    .expect("multi_area_object_range Address")
            ),
            "$A$1:$A$2,$C$1:$C$2"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(multi_area_object_areas, "Count", &[])
                    .expect("multi_area_object_range Areas.Count")
            ),
            2.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection_after_multi_area_object, "Address", &[])
                    .expect("Selection after Range(multi_area_source) Address")
            ),
            "$A$1:$A$2,$C$1:$C$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(mixed_range, "Address", &[])
                    .expect("mixed_range Address")
            ),
            "$A$1:$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(text_object_range, "Address", &[])
                    .expect("text_object_range Address")
            ),
            "$A$1:$B$2"
        );
        assert_eq!(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Object(active_workbook)])
                .expect_err("Range(workbook) should fail")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Object(foreign_cell)])
                .expect_err("Range(foreign_cell) should fail")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Object(multi_area_source), OmValue::Object(cell_b2)]
                )
                .expect_err("Range(multi_area_source, cell_b2) should fail")
                .code,
            OmErrorCode::Unsupported
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Object(cell_a1), OmValue::Object(multi_area_source)]
                )
                .expect_err("Range(cell_a1, multi_area_source) should fail")
                .code,
            OmErrorCode::Unsupported
        );
    }

    #[test]
    fn range_dispatch_round_trips_array_value2() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let sheet_id = runtime.worksheets(workbook).expect("worksheets")[0].id;
        let application = runtime.root_application();
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B2".to_string())])
                .expect("Range(A1:B2)"),
        );

        runtime
            .dispatch_set(
                range,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        2,
                        2,
                        vec![
                            OmValue::Number(1.0),
                            OmValue::Text("two".to_string()),
                            OmValue::Bool(true),
                            OmValue::Empty,
                        ],
                    )
                    .expect("array"),
                ),
                &[],
            )
            .expect("set array Value2");

        let value = runtime
            .dispatch_get(range, "Value2", &[])
            .expect("get array Value2");
        let OmValue::Array(array) = value else {
            panic!("expected OmValue::Array");
        };

        assert_eq!(array.rows, 2);
        assert_eq!(array.cols, 2);
        assert_eq!(array.values[0], OmValue::Number(1.0));
        assert_eq!(array.values[1], OmValue::Text("two".to_string()));
        assert_eq!(array.values[2], OmValue::Bool(true));
        assert_eq!(array.values[3], OmValue::Empty);

        let updated = runtime
            .get_range_values(GetRangeValuesSpec {
                workbook,
                range: RangeRef::single_rect(
                    WorkbookId(1),
                    sheet_id,
                    Rect {
                        row_first: 1,
                        row_last: 2,
                        col_first: 1,
                        col_last: 2,
                    },
                ),
            })
            .expect("updated range");
        assert_eq!(updated.values, array.values);
    }

