    #[test]
    fn range_multi_area_fill_methods_apply_each_area() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );

        let a1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Range(A1)"),
        );
        let e1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("E1".to_string())])
                .expect("Range(E1)"),
        );
        runtime
            .dispatch_set(a1, "Value2", OmValue::Number(11.0), &[])
            .expect("A1.Value2");
        runtime
            .dispatch_set(e1, "Value2", OmValue::Number(22.0), &[])
            .expect("E1.Value2");
        let fill_down = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("A1:A3,E1:E3".to_string())],
                )
                .expect("Range(A1:A3,E1:E3)"),
        );
        runtime
            .dispatch_invoke(fill_down, "FillDown", &[])
            .expect("multi-area FillDown");

        let c5_c6 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("C5:C6".to_string())])
                .expect("Range(C5:C6)"),
        );
        let g5_g6 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("G5:G6".to_string())])
                .expect("Range(G5:G6)"),
        );
        runtime
            .dispatch_set(
                c5_c6,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        2,
                        1,
                        vec![OmValue::Number(7.0), OmValue::Text("left".to_string())],
                    )
                    .expect("C5:C6 values"),
                ),
                &[],
            )
            .expect("C5:C6.Value2");
        runtime
            .dispatch_set(
                g5_g6,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        2,
                        1,
                        vec![OmValue::Number(8.0), OmValue::Text("right".to_string())],
                    )
                    .expect("G5:G6 values"),
                ),
                &[],
            )
            .expect("G5:G6.Value2");
        let fill_right = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("C5:D6,G5:H6".to_string())],
                )
                .expect("Range(C5:D6,G5:H6)"),
        );
        runtime
            .dispatch_invoke(fill_right, "FillRight", &[])
            .expect("multi-area FillRight");

        let a10 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A10".to_string())])
                .expect("Range(A10)"),
        );
        let e10 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("E10".to_string())])
                .expect("Range(E10)"),
        );
        runtime
            .dispatch_set(a10, "Value2", OmValue::Number(31.0), &[])
            .expect("A10.Value2");
        runtime
            .dispatch_set(e10, "Value2", OmValue::Number(32.0), &[])
            .expect("E10.Value2");
        let fill_up = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("A8:A10,E8:E10".to_string())],
                )
                .expect("Range(A8:A10,E8:E10)"),
        );
        runtime
            .dispatch_invoke(fill_up, "FillUp", &[])
            .expect("multi-area FillUp");

        let d12 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("D12".to_string())])
                .expect("Range(D12)"),
        );
        let h12 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("H12".to_string())])
                .expect("Range(H12)"),
        );
        runtime
            .dispatch_set(d12, "Value2", OmValue::Number(41.0), &[])
            .expect("D12.Value2");
        runtime
            .dispatch_set(h12, "Value2", OmValue::Number(42.0), &[])
            .expect("H12.Value2");
        let fill_left = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("C12:D12,G12:H12".to_string())],
                )
                .expect("Range(C12:D12,G12:H12)"),
        );
        runtime
            .dispatch_invoke(fill_left, "FillLeft", &[])
            .expect("multi-area FillLeft");

        for (address, expected) in [
            ("A3", OmValue::Number(11.0)),
            ("E3", OmValue::Number(22.0)),
            ("D5", OmValue::Number(7.0)),
            ("H6", OmValue::Text("right".to_string())),
            ("A8", OmValue::Number(31.0)),
            ("E8", OmValue::Number(32.0)),
            ("C12", OmValue::Number(41.0)),
            ("G12", OmValue::Number(42.0)),
        ] {
            let cell = expect_object_handle(
                runtime
                    .dispatch_invoke(active_sheet, "Range", &[OmValue::Text(address.to_string())])
                    .expect("cell Range"),
            );
            assert_eq!(
                runtime
                    .dispatch_get(cell, "Value2", &[])
                    .expect("filled cell Value2"),
                expected,
                "{address} should be filled from its own area"
            );
        }
        assert_eq!(
            runtime
                .dispatch_invoke(fill_down, "FillDown", &[OmValue::Missing])
                .expect_err("multi-area FillDown should reject arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn range_fill_dispatch_rejects_arguments_and_read_only_workbooks() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B2".to_string())])
                .expect("Range(A1:B2)"),
        );
        assert_eq!(
            runtime
                .dispatch_invoke(range, "FillDown", &[OmValue::Missing])
                .expect_err("Range.FillDown should reject arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(range, "FillRight", &[OmValue::Missing])
                .expect_err("Range.FillRight should reject arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(range, "FillUp", &[OmValue::Missing])
                .expect_err("Range.FillUp should reject arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(range, "FillLeft", &[OmValue::Missing])
                .expect_err("Range.FillLeft should reject arguments")
                .code,
            OmErrorCode::InvalidArgument
        );

        let mut read_only_runtime = ExcelRuntime::new();
        read_only_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: true,
            })
            .expect("open read-only workbook");
        let read_only_sheet = expect_object_handle(
            read_only_runtime
                .dispatch_get(read_only_runtime.root_application(), "ActiveSheet", &[])
                .expect("read-only ActiveSheet"),
        );
        let read_only_range = expect_object_handle(
            read_only_runtime
                .dispatch_invoke(
                    read_only_sheet,
                    "Range",
                    &[OmValue::Text("A1:B2".to_string())],
                )
                .expect("read-only Range(A1:B2)"),
        );
        assert_eq!(
            read_only_runtime
                .dispatch_invoke(read_only_range, "FillDown", &[])
                .expect_err("Range.FillDown should reject read-only workbooks")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            read_only_runtime
                .dispatch_invoke(read_only_range, "FillRight", &[])
                .expect_err("Range.FillRight should reject read-only workbooks")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            read_only_runtime
                .dispatch_invoke(read_only_range, "FillUp", &[])
                .expect_err("Range.FillUp should reject read-only workbooks")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            read_only_runtime
                .dispatch_invoke(read_only_range, "FillLeft", &[])
                .expect_err("Range.FillLeft should reject read-only workbooks")
                .code,
            OmErrorCode::InvalidState
        );
    }

    #[test]
    fn application_range_dispatch_targets_the_active_sheet() {
        let mut runtime = ExcelRuntime::new();
        let workbook1 = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook1");
        let workbook2 = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook2");
        let worksheets1 = expect_object_handle(
            runtime
                .dispatch_get(workbook1.0, "Worksheets", &[])
                .expect("Workbook1.Worksheets"),
        );
        let worksheet1 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets1, "Item", &[OmValue::Number(1.0)])
                .expect("Workbook1.Worksheets.Item(1)"),
        );
        let worksheets2 = expect_object_handle(
            runtime
                .dispatch_get(workbook2.0, "Worksheets", &[])
                .expect("Workbook2.Worksheets"),
        );
        let worksheet2 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets2, "Item", &[OmValue::Number(1.0)])
                .expect("Workbook2.Worksheets.Item(1)"),
        );

        runtime
            .dispatch_set(
                worksheet1,
                "Name",
                OmValue::Text("FirstSheet".to_string()),
                &[],
            )
            .expect("rename workbook1 sheet");
        runtime
            .dispatch_set(
                worksheet2,
                "Name",
                OmValue::Text("SecondSheet".to_string()),
                &[],
            )
            .expect("rename workbook2 sheet");
        runtime
            .dispatch_invoke(worksheet1, "Activate", &[])
            .expect("Worksheet.Activate");

        let application = runtime.root_application();
        let application_range = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Range", &[OmValue::Text("B1:C1".to_string())])
                .expect("Application.Range(B1:C1)"),
        );
        let active_workbook = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveWorkbook", &[])
                .expect("ActiveWorkbook after Application.Range"),
        );
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet after Application.Range"),
        );
        let active_cell = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveCell", &[])
                .expect("ActiveCell after Application.Range"),
        );
        let selection = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after Application.Range"),
        );
        let range_parent = expect_object_handle(
            runtime
                .dispatch_get(application_range, "Parent", &[])
                .expect("Application.Range parent"),
        );

        assert_eq!(active_workbook, workbook1.0);
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(application_range, "Address", &[])
                    .expect("Application.Range address")
            ),
            "$B$1:$C$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_sheet, "Name", &[])
                    .expect("ActiveSheet after Application.Range name")
            ),
            "FirstSheet"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(range_parent, "Name", &[])
                    .expect("Application.Range parent name")
            ),
            "FirstSheet"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection, "Address", &[])
                    .expect("Selection after Application.Range address")
            ),
            "$B$1:$C$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_cell, "Address", &[])
                    .expect("ActiveCell after Application.Range address")
            ),
            "$B$1"
        );

        let mut empty_runtime = ExcelRuntime::new();
        assert_eq!(
            empty_runtime
                .dispatch_invoke(
                    empty_runtime.root_application(),
                    "Range",
                    &[OmValue::Text("A1".to_string())],
                )
                .expect_err("Application.Range without active workbook")
                .code,
            OmErrorCode::InvalidState
        );
    }

    #[test]
    fn application_range_accepts_sheet_qualified_string_references() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let sheet1 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("Worksheets.Item(1)"),
        );
        let sheet2 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Add", &[])
                .expect("Worksheets.Add Sheet2"),
        );
        runtime
            .dispatch_set(sheet1, "Name", OmValue::Text("FirstSheet".to_string()), &[])
            .expect("rename first sheet");
        runtime
            .dispatch_set(
                sheet2,
                "Name",
                OmValue::Text("Quarter 1's Data".to_string()),
                &[],
            )
            .expect("rename second sheet");
        runtime
            .dispatch_invoke(sheet1, "Activate", &[])
            .expect("Worksheet.Activate");

        let application = runtime.root_application();
        let qualified_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    application,
                    "Range",
                    &[OmValue::Text("'quarter 1''s data'!C4:D5".to_string())],
                )
                .expect("Application.Range on quoted sheet reference"),
        );
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet after qualified Application.Range"),
        );
        let selection = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after qualified Application.Range"),
        );
        let range_parent = expect_object_handle(
            runtime
                .dispatch_get(qualified_range, "Parent", &[])
                .expect("qualified Application.Range parent"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(qualified_range, "Address", &[])
                    .expect("qualified Application.Range address")
            ),
            "$C$4:$D$5"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(range_parent, "Name", &[])
                    .expect("qualified Application.Range parent name")
            ),
            "Quarter 1's Data"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_sheet, "Name", &[])
                    .expect("ActiveSheet after qualified Application.Range name")
            ),
            "Quarter 1's Data"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection, "Address", &[])
                    .expect("Selection after qualified Application.Range address")
            ),
            "$C$4:$D$5"
        );

        let external_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    application,
                    "Range",
                    &[OmValue::Text(
                        "'[Workbook]Quarter 1''s Data'!A2:B3".to_string(),
                    )],
                )
                .expect("Application.Range on external sheet reference"),
        );
        let external_parent = expect_object_handle(
            runtime
                .dispatch_get(external_range, "Parent", &[])
                .expect("external Application.Range parent"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(external_range, "Address", &[])
                    .expect("external Application.Range address")
            ),
            "$A$2:$B$3"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(external_parent, "Name", &[])
                    .expect("external Application.Range parent name")
            ),
            "Quarter 1's Data"
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    application,
                    "Range",
                    &[OmValue::Text("[Missing]FirstSheet!A1".to_string())],
                )
                .expect_err("Application.Range should reject unknown workbooks")
                .code,
            OmErrorCode::NotFound
        );
    }

    #[test]
    fn application_intersect_returns_overlaps_without_mutating_selection() {
        let mut runtime = ExcelRuntime::new();
        let workbook1 = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook1");
        let workbook2 = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook2");
        let worksheets1 = expect_object_handle(
            runtime
                .dispatch_get(workbook1.0, "Worksheets", &[])
                .expect("Workbook1.Worksheets"),
        );
        let worksheet1 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets1, "Item", &[OmValue::Number(1.0)])
                .expect("Workbook1.Worksheets.Item(1)"),
        );
        let worksheets2 = expect_object_handle(
            runtime
                .dispatch_get(workbook2.0, "Worksheets", &[])
                .expect("Workbook2.Worksheets"),
        );
        let worksheet2 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets2, "Item", &[OmValue::Number(1.0)])
                .expect("Workbook2.Worksheets.Item(1)"),
        );

        runtime
            .dispatch_invoke(worksheet1, "Activate", &[])
            .expect("Worksheet.Activate");

        let application = runtime.root_application();
        let range1 = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Range", &[OmValue::Text("A1:B2".to_string())])
                .expect("Application.Range(A1:B2)"),
        );
        let range2 = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Range", &[OmValue::Text("B2:C3".to_string())])
                .expect("Application.Range(B2:C3)"),
        );
        let range3 = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Range", &[OmValue::Text("B1:B5".to_string())])
                .expect("Application.Range(B1:B5)"),
        );
        let overlap = expect_object_handle(
            runtime
                .dispatch_invoke(
                    application,
                    "Intersect",
                    &[OmValue::Object(range1), OmValue::Object(range2)],
                )
                .expect("Application.Intersect(range1, range2)"),
        );
        let multi_overlap = expect_object_handle(
            runtime
                .dispatch_invoke(
                    application,
                    "Intersect",
                    &[
                        OmValue::Object(range1),
                        OmValue::Object(range2),
                        OmValue::Object(range3),
                    ],
                )
                .expect("Application.Intersect(range1, range2, range3)"),
        );
        let thirty_overlap_args = vec![OmValue::Object(range1); 30];
        let thirty_overlap = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Intersect", &thirty_overlap_args)
                .expect("Application.Intersect with 30 args"),
        );
        let selection_after_intersect = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after Intersect"),
        );
        let disjoint = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Range", &[OmValue::Text("D4".to_string())])
                .expect("Application.Range(D4)"),
        );
        let foreign_range = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet2, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Workbook2.Range(A1)"),
        );
        let multi_area_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    application,
                    "Range",
                    &[OmValue::Text("A1:A3,C1:C3".to_string())],
                )
                .expect("Application.Range(A1:A3,C1:C3)"),
        );
        let row_mask = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Range", &[OmValue::Text("A2:C2".to_string())])
                .expect("Application.Range(A2:C2)"),
        );
        let pairwise_overlap = expect_object_handle(
            runtime
                .dispatch_invoke(
                    application,
                    "Intersect",
                    &[OmValue::Object(multi_area_range), OmValue::Object(row_mask)],
                )
                .expect("Application.Intersect multi-area pairwise"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(overlap, "Address", &[])
                    .expect("Application.Intersect overlap address")
            ),
            "$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(pairwise_overlap, "Address", &[])
                    .expect("Application.Intersect pairwise overlap address")
            ),
            "$A$2,$C$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(multi_overlap, "Address", &[])
                    .expect("Application.Intersect multi-arg overlap address")
            ),
            "$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(thirty_overlap, "Address", &[])
                    .expect("Application.Intersect 30-arg overlap address")
            ),
            "$A$1:$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection_after_intersect, "Address", &[])
                    .expect("Selection after Intersect address")
            ),
            "$B$1:$B$5"
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    application,
                    "Intersect",
                    &[OmValue::Object(range1), OmValue::Object(disjoint)],
                )
                .expect("Application.Intersect disjoint"),
            OmValue::Empty
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    application,
                    "Intersect",
                    &[
                        OmValue::Object(range1),
                        OmValue::Object(range2),
                        OmValue::Object(disjoint),
                    ],
                )
                .expect("Application.Intersect multi-arg disjoint"),
            OmValue::Empty
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    application,
                    "Intersect",
                    &[OmValue::Object(range1), OmValue::Object(foreign_range)],
                )
                .expect_err("Application.Intersect should reject foreign ranges")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(application, "Intersect", &[OmValue::Object(range1)])
                .expect_err("Application.Intersect requires two args")
                .code,
            OmErrorCode::InvalidArgument
        );
        let too_many_args = vec![OmValue::Object(range1); 31];
        assert_eq!(
            runtime
                .dispatch_invoke(application, "Intersect", &too_many_args)
                .expect_err("Application.Intersect should reject more than 30 args")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    application,
                    "Intersect",
                    &[OmValue::Object(range1), OmValue::Object(workbook1.0)],
                )
                .expect_err("Application.Intersect should reject non-range objects")
                .code,
            OmErrorCode::TypeMismatch
        );
    }

    #[test]
    fn application_union_preserves_multi_area_results_in_argument_order() {
        let mut runtime = ExcelRuntime::new();
        let workbook1 = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook1");
        let workbook2 = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook2");
        let worksheets1 = expect_object_handle(
            runtime
                .dispatch_get(workbook1.0, "Worksheets", &[])
                .expect("Workbook1.Worksheets"),
        );
        let worksheet1 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets1, "Item", &[OmValue::Number(1.0)])
                .expect("Workbook1.Worksheets.Item(1)"),
        );
        let worksheets2 = expect_object_handle(
            runtime
                .dispatch_get(workbook2.0, "Worksheets", &[])
                .expect("Workbook2.Worksheets"),
        );
        let worksheet2 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets2, "Item", &[OmValue::Number(1.0)])
                .expect("Workbook2.Worksheets.Item(1)"),
        );

        runtime
            .dispatch_invoke(worksheet1, "Activate", &[])
            .expect("Worksheet.Activate");

        let application = runtime.root_application();
        let range1 = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Range", &[OmValue::Text("A1:B2".to_string())])
                .expect("Application.Range(A1:B2)"),
        );
        let range2 = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Range", &[OmValue::Text("B1:C2".to_string())])
                .expect("Application.Range(B1:C2)"),
        );
        let union = expect_object_handle(
            runtime
                .dispatch_invoke(
                    application,
                    "Union",
                    &[OmValue::Object(range1), OmValue::Object(range2)],
                )
                .expect("Application.Union(range1, range2)"),
        );
        let selection_after_union = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after Union"),
        );
        let disjoint = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Range", &[OmValue::Text("E1".to_string())])
                .expect("Application.Range(E1)"),
        );
        let range3 = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Range", &[OmValue::Text("D1:D2".to_string())])
                .expect("Application.Range(D1:D2)"),
        );
        let multi_union = expect_object_handle(
            runtime
                .dispatch_invoke(
                    application,
                    "Union",
                    &[
                        OmValue::Object(range1),
                        OmValue::Object(range2),
                        OmValue::Object(range3),
                    ],
                )
                .expect("Application.Union(range1, range2, range3)"),
        );
        let thirty_union_args = vec![OmValue::Object(range1); 30];
        let thirty_union = expect_object_handle(
            runtime
                .dispatch_invoke(application, "Union", &thirty_union_args)
                .expect("Application.Union with 30 args"),
        );
        let foreign_range = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet2, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Workbook2.Range(A1)"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(union, "Address", &[])
                    .expect("Application.Union address")
            ),
            "$A$1:$B$2,$B$1:$C$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(multi_union, "Address", &[])
                    .expect("Application.Union multi-arg address")
            ),
            "$A$1:$B$2,$B$1:$C$2,$D$1:$D$2"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(thirty_union, "Count", &[])
                    .expect("Application.Union 30-arg count")
            ),
            120.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection_after_union, "Address", &[])
                    .expect("Selection after Union address")
            ),
            "$B$1:$C$2"
        );
        let disjoint_union = expect_object_handle(
            runtime
                .dispatch_invoke(
                    application,
                    "Union",
                    &[OmValue::Object(range1), OmValue::Object(disjoint)],
                )
                .expect("Application.Union should allow disjoint multi-area results"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(disjoint_union, "Address", &[])
                    .expect("disjoint union address")
            ),
            "$A$1:$B$2,$E$1"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(disjoint_union, "Count", &[])
                    .expect("disjoint union count")
            ),
            5.0
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    application,
                    "Union",
                    &[OmValue::Object(range1), OmValue::Object(foreign_range)],
                )
                .expect_err("Application.Union should reject foreign ranges")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(application, "Union", &[OmValue::Object(range1)])
                .expect_err("Application.Union requires two args")
                .code,
            OmErrorCode::InvalidArgument
        );
        let too_many_args = vec![OmValue::Object(range1); 31];
        assert_eq!(
            runtime
                .dispatch_invoke(application, "Union", &too_many_args)
                .expect_err("Application.Union should reject more than 30 args")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    application,
                    "Union",
                    &[OmValue::Object(range1), OmValue::Object(workbook1.0)],
                )
                .expect_err("Application.Union should reject non-range objects")
                .code,
            OmErrorCode::TypeMismatch
        );
    }

    #[test]
    fn application_cells_dispatch_targets_the_active_sheet_and_supports_index_args() {
        let mut runtime = ExcelRuntime::new();
        let workbook1 = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook1");
        let workbook2 = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook2");
        let worksheets1 = expect_object_handle(
            runtime
                .dispatch_get(workbook1.0, "Worksheets", &[])
                .expect("Workbook1.Worksheets"),
        );
        let worksheet1 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets1, "Item", &[OmValue::Number(1.0)])
                .expect("Workbook1.Worksheets.Item(1)"),
        );
        let worksheets2 = expect_object_handle(
            runtime
                .dispatch_get(workbook2.0, "Worksheets", &[])
                .expect("Workbook2.Worksheets"),
        );
        let worksheet2 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets2, "Item", &[OmValue::Number(1.0)])
                .expect("Workbook2.Worksheets.Item(1)"),
        );

        runtime
            .dispatch_set(
                worksheet1,
                "Name",
                OmValue::Text("FirstSheet".to_string()),
                &[],
            )
            .expect("rename workbook1 sheet");
        runtime
            .dispatch_set(
                worksheet2,
                "Name",
                OmValue::Text("SecondSheet".to_string()),
                &[],
            )
            .expect("rename workbook2 sheet");
        runtime
            .dispatch_invoke(worksheet1, "Activate", &[])
            .expect("Worksheet.Activate");

        let application = runtime.root_application();
        let full_cells = expect_object_handle(
            runtime
                .dispatch_get(application, "Cells", &[])
                .expect("Application.Cells"),
        );
        let indexed_cell = expect_object_handle(
            runtime
                .dispatch_get(
                    application,
                    "Cells",
                    &[OmValue::Number(2.0), OmValue::Text("B".to_string())],
                )
                .expect("Application.Cells(2, \"B\")"),
        );
        let active_workbook = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveWorkbook", &[])
                .expect("ActiveWorkbook after Application.Cells"),
        );
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet after Application.Cells"),
        );
        let active_cell = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveCell", &[])
                .expect("ActiveCell after Application.Cells"),
        );
        let selection = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after Application.Cells"),
        );

        assert_eq!(active_workbook, workbook1.0);
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(full_cells, "Address", &[])
                    .expect("Application.Cells address")
            ),
            "$A$1:$XFD$1048576"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(indexed_cell, "Address", &[])
                    .expect("Application.Cells(2, \"B\") address")
            ),
            "$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_sheet, "Name", &[])
                    .expect("ActiveSheet after Application.Cells name")
            ),
            "FirstSheet"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection, "Address", &[])
                    .expect("Selection after Application.Cells address")
            ),
            "$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_cell, "Address", &[])
                    .expect("ActiveCell after Application.Cells address")
            ),
            "$B$2"
        );

        let mut empty_runtime = ExcelRuntime::new();
        let empty_application = empty_runtime.root_application();
        assert_eq!(
            empty_runtime
                .dispatch_get(empty_application, "Cells", &[])
                .expect("Application.Cells without active workbook"),
            OmValue::Empty
        );
    }

