    #[test]
    fn application_goto_selects_ranges_and_activates_foreign_workbooks() {
        let mut runtime = ExcelRuntime::new();
        let workbook1 = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook1");
        let workbook2 = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook2");
        let worksheets1 = expect_object_handle(
            runtime
                .dispatch_get(workbook1.0, "Worksheets", &[])
                .expect("Workbook1.Worksheets"),
        );
        let worksheet1 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets1, "Item", &[OmValue::Number(1.0)])
                .expect("Workbook1.Worksheets.Item(1)"),
        );
        let worksheets2 = expect_object_handle(
            runtime
                .dispatch_get(workbook2.0, "Worksheets", &[])
                .expect("Workbook2.Worksheets"),
        );
        let worksheet2 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets2, "Item", &[OmValue::Number(1.0)])
                .expect("Workbook2.Worksheets.Item(1)"),
        );

        runtime
            .dispatch_set(
                worksheet1,
                "Name",
                OmValue::Text("FirstSheet".to_string()),
                &[],
            )
            .expect("rename workbook1 sheet");
        runtime
            .dispatch_set(
                worksheet2,
                "Name",
                OmValue::Text("SecondSheet".to_string()),
                &[],
            )
            .expect("rename workbook2 sheet");
        runtime
            .dispatch_invoke(worksheet1, "Activate", &[])
            .expect("Worksheet.Activate");

        let foreign_range = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet2, "Range", &[OmValue::Text("B3:C4".to_string())])
                .expect("Workbook2.Range(B3:C4)"),
        );
        let application = runtime.root_application();

        assert!(matches!(
            runtime
                .dispatch_invoke(application, "Goto", &[OmValue::Object(foreign_range)])
                .expect("Application.Goto(range)"),
            OmValue::Empty
        ));

        let active_workbook = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveWorkbook", &[])
                .expect("ActiveWorkbook after Application.Goto(range)"),
        );
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet after Application.Goto(range)"),
        );
        let active_cell = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveCell", &[])
                .expect("ActiveCell after Application.Goto(range)"),
        );
        let selection = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after Application.Goto(range)"),
        );

        assert_eq!(active_workbook, workbook2.0);
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_sheet, "Name", &[])
                    .expect("ActiveSheet after Application.Goto(range) name")
            ),
            "SecondSheet"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection, "Address", &[])
                    .expect("Selection after Application.Goto(range) address")
            ),
            "$B$3:$C$4"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_cell, "Address", &[])
                    .expect("ActiveCell after Application.Goto(range) address")
            ),
            "$B$3"
        );

        let foreign_multi_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    worksheet2,
                    "Range",
                    &[OmValue::Text("A1:A2,C1:C2".to_string())],
                )
                .expect("Workbook2.Range(A1:A2,C1:C2)"),
        );
        assert!(matches!(
            runtime
                .dispatch_invoke(application, "Goto", &[OmValue::Object(foreign_multi_range)])
                .expect("Application.Goto(multi-area range)"),
            OmValue::Empty
        ));
        let multi_selection = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after Application.Goto(multi-area range)"),
        );
        let multi_selection_areas = expect_object_handle(
            runtime
                .dispatch_get(multi_selection, "Areas", &[])
                .expect("Selection.Areas after Application.Goto(multi-area range)"),
        );
        let active_cell_after_multi = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveCell", &[])
                .expect("ActiveCell after Application.Goto(multi-area range)"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(multi_selection, "Address", &[])
                    .expect("Selection after Application.Goto(multi-area range) address")
            ),
            "$A$1:$A$2,$C$1:$C$2"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(multi_selection_areas, "Count", &[])
                    .expect("Selection.Areas.Count after Application.Goto(multi-area range)")
            ),
            2.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_cell_after_multi, "Address", &[])
                    .expect("ActiveCell after Application.Goto(multi-area range) address")
            ),
            "$A$1"
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(
                    application,
                    "Goto",
                    &[OmValue::Text("E1:E2,G1:G2".to_string())],
                )
                .expect("Application.Goto(multi-area text)"),
            OmValue::Empty
        ));
        let multi_text_selection = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after Application.Goto(multi-area text)"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(multi_text_selection, "Address", &[])
                    .expect("Selection after Application.Goto(multi-area text) address")
            ),
            "$E$1:$E$2,$G$1:$G$2"
        );
        assert!(matches!(
            runtime
                .dispatch_invoke(application, "Goto", &[])
                .expect("Application.Goto without reference repeats multi-area goto"),
            OmValue::Empty
        ));
        let repeated_multi_selection = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after repeated multi-area Application.Goto"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(repeated_multi_selection, "Address", &[])
                    .expect("Selection after repeated multi-area Application.Goto address")
            ),
            "$E$1:$E$2,$G$1:$G$2"
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(
                    application,
                    "Goto",
                    &[OmValue::Text("D5".to_string()), OmValue::Bool(true)],
                )
                .expect("Application.Goto(\"D5\", true)"),
            OmValue::Empty
        ));
        let selection_after_text = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after Application.Goto(\"D5\")"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(selection_after_text, "Address", &[])
                    .expect("Selection after Application.Goto(\"D5\") address")
            ),
            "$D$5"
        );
        assert!(matches!(
            runtime
                .dispatch_invoke(application, "Goto", &[])
                .expect("Application.Goto without reference repeats last goto"),
            OmValue::Empty
        ));
        let repeated_selection = expect_object_handle(
            runtime
                .dispatch_get(application, "Selection", &[])
                .expect("Selection after repeated Application.Goto"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(repeated_selection, "Address", &[])
                    .expect("Selection after repeated Application.Goto address")
            ),
            "$D$5"
        );
        assert_eq!(
            runtime
                .dispatch_invoke(application, "Goto", &[OmValue::Object(workbook1.0)])
                .expect_err("Application.Goto should reject non-range objects")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    application,
                    "Goto",
                    &[
                        OmValue::Text("A1".to_string()),
                        OmValue::Text("bad".to_string())
                    ],
                )
                .expect_err("Application.Goto should reject non-bool scroll values")
                .code,
            OmErrorCode::TypeMismatch
        );

        let mut empty_runtime = ExcelRuntime::new();
        let empty_application = empty_runtime.root_application();
        assert_eq!(
            empty_runtime
                .dispatch_invoke(empty_application, "Goto", &[])
                .expect_err("Application.Goto without prior goto should fail")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            empty_runtime
                .dispatch_invoke(
                    empty_application,
                    "Goto",
                    &[OmValue::Text("A1".to_string())],
                )
                .expect_err("Application.Goto without active workbook")
                .code,
            OmErrorCode::InvalidState
        );
    }

