    #[test]
    fn chart_sheet_chart_handle_activate_and_delete() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let charts = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Charts", &[])
                .expect("Workbook.Charts"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_invoke(charts, "Add", &[])
                .expect("Charts.Add"),
        );
        let chart_area = expect_object_handle(
            runtime
                .dispatch_get(chart, "ChartArea", &[])
                .expect("Chart.ChartArea"),
        );
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("Worksheets.Item(1)"),
        );
        runtime
            .dispatch_invoke(worksheet, "Activate", &[])
            .expect("Worksheet.Activate");
        assert_eq!(
            runtime
                .dispatch_get(application, "ActiveChart", &[])
                .expect("ActiveChart after Worksheet.Activate"),
            OmValue::Empty
        );

        runtime
            .dispatch_invoke(chart, "Select", &[])
            .expect("Chart.Select");
        let active_chart = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveChart", &[])
                .expect("ActiveChart after Chart.Select"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_chart, "Name", &[])
                    .expect("ActiveChart.Name after Chart.Select")
            ),
            "Chart1"
        );
        runtime
            .dispatch_invoke(worksheet, "Activate", &[])
            .expect("Worksheet.Activate clears Chart.Select");
        assert_eq!(
            runtime
                .dispatch_get(application, "ActiveChart", &[])
                .expect("ActiveChart after Worksheet.Activate following Chart.Select"),
            OmValue::Empty
        );
        runtime
            .dispatch_invoke(chart, "Select", &[OmValue::Bool(false)])
            .expect("Chart.Select with Replace");
        let active_chart = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveChart", &[])
                .expect("ActiveChart after Chart.Select Replace"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_chart, "Name", &[])
                    .expect("ActiveChart.Name after Chart.Select Replace")
            ),
            "Chart1"
        );
        runtime
            .dispatch_invoke(worksheet, "Activate", &[])
            .expect("Worksheet.Activate clears Chart.Select Replace");
        assert_eq!(
            runtime
                .dispatch_invoke(chart, "Select", &[OmValue::Text("bad".to_string())])
                .expect_err("Chart.Select rejects non-bool Replace")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    chart,
                    "Select",
                    &[OmValue::Bool(true), OmValue::Bool(false)]
                )
                .expect_err("Chart.Select rejects extra args")
                .code,
            OmErrorCode::InvalidArgument
        );

        runtime
            .dispatch_invoke(chart, "Activate", &[])
            .expect("Chart.Activate");
        let active_chart = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveChart", &[])
                .expect("ActiveChart after Chart.Activate"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_chart, "Name", &[])
                    .expect("ActiveChart.Name")
            ),
            "Chart1"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_invoke(chart, "Evaluate", &[OmValue::Text("=1+1".to_string())])
                    .expect("chart sheet Chart.Evaluate scalar formula")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_invoke(
                        chart,
                        "Evaluate",
                        &[OmValue::Text("=Sheet1!A1+1".to_string())]
                    )
                    .expect("chart sheet Chart.Evaluate worksheet-qualified formula")
            ),
            43.0
        );
        runtime
            .dispatch_set(application, "DisplayAlerts", OmValue::Bool(false), &[])
            .expect("disable DisplayAlerts");
        assert_eq!(
            runtime
                .dispatch_invoke(chart, "Delete", &[])
                .expect("Chart.Delete"),
            OmValue::Bool(true)
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(charts, "Count", &[])
                    .expect("Charts.Count after Chart.Delete")
            ),
            0.0
        );
        assert_eq!(
            runtime
                .dispatch_get(application, "ActiveChart", &[])
                .expect("ActiveChart after Chart.Delete"),
            OmValue::Empty
        );
        assert_eq!(
            runtime
                .dispatch_get(chart, "ChartType", &[])
                .expect_err("deleted chart sheet Chart handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_invoke(chart_area, "Select", &[])
                .expect_err("deleted chart sheet ChartArea handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );
        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after Chart.Delete");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved Chart.Delete package");
        assert!(!saved_package.contains("xl/chartsheets/sheet1.xml"));
        assert!(!saved_package.contains("xl/drawings/drawing1.xml"));
        assert!(!saved_package.contains("xl/charts/chart1.xml"));
    }

