        assert!(saved_chart_xml.contains("<a:t>Revenue &amp; Trend &lt;2026&gt;</a:t>"));
        assert!(!saved_chart_xml.contains("Revenue &amp; Trend &lt;2026&gt;&amp;&lt;&gt;"));

