    #[test]
    fn chart_area_and_plot_area_clear_methods_reject_read_only_workbook() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: true,
            })
            .expect("open read-only workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let chart_area = expect_object_handle(
            runtime
                .dispatch_get(chart, "ChartArea", &[])
                .expect("Chart.ChartArea"),
        );
        let plot_area = expect_object_handle(
            runtime
                .dispatch_get(chart, "PlotArea", &[])
                .expect("Chart.PlotArea"),
        );

        for (handle, owner, member) in [
            (chart_area, "ChartArea", "Clear"),
            (chart_area, "ChartArea", "ClearContents"),
            (chart_area, "ChartArea", "ClearFormats"),
            (plot_area, "PlotArea", "Clear"),
            (plot_area, "PlotArea", "ClearContents"),
            (plot_area, "PlotArea", "ClearFormats"),
        ] {
            let error = match runtime.dispatch_invoke(handle, member, &[]) {
                Ok(_) => panic!("{owner}.{member} should reject read-only workbooks"),
                Err(error) => error,
            };
            assert_eq!(
                error.code,
                OmErrorCode::InvalidState,
                "{owner}.{member}: {error:?}"
            );
            assert!(
                error.message.contains("read-only"),
                "{owner}.{member}: {error:?}"
            );
        }
    }

    #[test]
    fn chartarea_clear_formats_resets_rounded_corners_and_preserves_extensions() {
        let mut package = OpcPackage::from_bytes(&synthetic_workbook_with_embedded_chart_bytes())
            .expect("embedded chart package");
        let chart_xml = String::from_utf8(
            package
                .part("xl/charts/chart1.xml")
                .expect("chart part")
                .bytes
                .clone(),
        )
        .expect("chart xml utf8")
        .replace(
            "</c:chartSpace>",
            r#"<c:extLst><c:ext uri="urn:chartarea-clear-formats-preserve"/></c:extLst></c:chartSpace>"#,
        );
        package
            .replace_part_bytes("xl/charts/chart1.xml", chart_xml.into_bytes())
            .expect("replace chart xml");

        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: package.to_bytes().expect("package bytes"),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let chart_area = expect_object_handle(
            runtime
                .dispatch_get(chart, "ChartArea", &[])
                .expect("Chart.ChartArea"),
        );

        runtime
            .dispatch_set(chart_area, "RoundedCorners", OmValue::Bool(true), &[])
            .expect("set ChartArea.RoundedCorners");
        assert_eq!(
            runtime
                .dispatch_get(chart_object, "RoundedCorners", &[])
                .expect("ChartObject.RoundedCorners before ClearFormats"),
            OmValue::Bool(true)
        );
        assert_eq!(
            runtime
                .dispatch_invoke(chart_area, "ClearFormats", &[OmValue::Missing])
                .expect_err("ChartArea.ClearFormats rejects arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
        let search_range = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet, "Range", &[OmValue::Text("A1:B3".to_string())])
                .expect("Worksheet.Range(A1:B3) before ChartArea.ClearFormats"),
        );
        runtime
            .dispatch_invoke(search_range, "Find", &[OmValue::Text("1".to_string())])
            .expect("Range.Find before ChartArea.ClearFormats");
        runtime
            .dispatch_invoke(search_range, "Copy", &[])
            .expect("Range.Copy before ChartArea.ClearFormats");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                    .expect("Application.CutCopyMode before ChartArea.ClearFormats")
            ),
            f64::from(super::XL_COPY)
        );
        assert_eq!(
            runtime
                .dispatch_invoke(chart_area, "ClearFormats", &[])
                .expect("ChartArea.ClearFormats"),
            OmValue::Empty
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                .expect("Application.CutCopyMode after ChartArea.ClearFormats")
        ));
        assert_eq!(
            runtime
                .dispatch_invoke(search_range, "FindNext", &[])
                .expect_err("Range.FindNext should require a new Find after ChartArea.ClearFormats")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(chart_area, "RoundedCorners", &[])
                .expect("ChartArea.RoundedCorners after ClearFormats"),
            OmValue::Bool(false)
        );
        assert_eq!(
            runtime
                .dispatch_get(chart_object, "RoundedCorners", &[])
                .expect("ChartObject.RoundedCorners after ClearFormats"),
            OmValue::Bool(false)
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after ChartArea.ClearFormats");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_chart_xml = std::str::from_utf8(
            saved_package
                .part("xl/charts/chart1.xml")
                .expect("saved chart part")
                .bytes
                .as_slice(),
        )
        .expect("saved chart xml utf8");
        assert!(saved_chart_xml.contains(r#"<c:ext uri="urn:chartarea-clear-formats-preserve"/>"#));
        assert!(!saved_chart_xml.contains("<c:roundedCorners"));

        let mut reopened_runtime = ExcelRuntime::new();
        let reopened_workbook = reopened_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen workbook after ChartArea.ClearFormats");
        let reopened_worksheet = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("reopened Workbook.Worksheets(1)"),
        );
        let reopened_chart_objects = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_worksheet, "ChartObjects", &[])
                .expect("reopened Worksheet.ChartObjects"),
        );
        let reopened_chart_object = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("reopened ChartObjects.Item(1)"),
        );
        let reopened_chart = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart_object, "Chart", &[])
                .expect("reopened ChartObject.Chart"),
        );
        let reopened_chart_area = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart, "ChartArea", &[])
                .expect("reopened Chart.ChartArea"),
        );
        assert_eq!(
            reopened_runtime
                .dispatch_get(reopened_chart_area, "RoundedCorners", &[])
                .expect("reopened ChartArea.RoundedCorners"),
            OmValue::Bool(false)
        );
    }

