    #[test]
    fn chart_set_default_chart_controls_new_embedded_and_chart_sheet_types() {
        let mut runtime = ExcelRuntime::new();
        let source_workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: true,
            })
            .expect("open read-only source chart");
        let source_worksheet = expect_object_handle(
            runtime
                .dispatch_get(
                    source_workbook.0,
                    "Worksheets",
                    &[OmValue::Number(1.0)],
                )
                .expect("source Workbook.Worksheets(1)"),
        );
        let source_chart_objects = expect_object_handle(
            runtime
                .dispatch_get(source_worksheet, "ChartObjects", &[])
                .expect("source Worksheet.ChartObjects"),
        );
        let source_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    source_chart_objects,
                    "Item",
                    &[OmValue::Number(1.0)],
                )
                .expect("source ChartObjects.Item(1)"),
        );
        let source_chart = expect_object_handle(
            runtime
                .dispatch_get(source_chart_object, "Chart", &[])
                .expect("source ChartObject.Chart"),
        );
        let original_chart_type = expect_number(
            runtime
                .dispatch_get(source_chart, "ChartType", &[])
                .expect("source Chart.ChartType"),
        );

        assert_eq!(
            runtime
                .dispatch_invoke(
                    source_chart,
                    "SetDefaultChart",
                    &[OmValue::Number(f64::from(super::XL_LINE))],
                )
                .expect("Chart.SetDefaultChart xlLine"),
            OmValue::Empty
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    source_chart,
                    "SetDefaultChart",
                    &[OmValue::Text("Monthly Sales".to_string())],
                )
                .expect_err("custom default chart templates are unavailable")
                .code,
            OmErrorCode::Unsupported
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    source_chart,
                    "SetDefaultChart",
                    &[OmValue::Number(99_999.0)],
                )
                .expect_err("unknown default chart type should fail")
                .code,
            OmErrorCode::Unsupported
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(source_chart, "ChartType", &[])
                    .expect("existing chart type after SetDefaultChart")
            ),
            original_chart_type
        );
        assert_eq!(
            runtime
                .dispatch_get(source_workbook.0, "Saved", &[])
                .expect("read-only source remains saved"),
            OmValue::Bool(true)
        );

        let application = runtime.root_application();
        let workbooks = expect_object_handle(
            runtime
                .dispatch_get(application, "Workbooks", &[])
                .expect("Application.Workbooks"),
        );
        let chart_workbook_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    workbooks,
                    "Add",
                    &[OmValue::Number(f64::from(super::XL_WBA_TEMPLATE_CHART))],
                )
                .expect("Workbooks.Add xlWBATChart after SetDefaultChart"),
        );
        let active_chart = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveChart", &[])
                .expect("ActiveChart after Workbooks.Add xlWBATChart"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(active_chart, "ChartType", &[])
                    .expect("new chart workbook ChartType")
            ),
            f64::from(super::XL_LINE)
        );
        let chart_workbook = office_common::WorkbookHandle(chart_workbook_object);
        let saved_chart_workbook = runtime
            .save_workbook(
                chart_workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save default line chart workbook");
        let reopened_chart_workbook = runtime
            .codec
            .load(&saved_chart_workbook, LoadOptions::default())
            .expect("reopen default line chart workbook");
        assert!(
            reopened_chart_workbook
                .state
                .charts
                .values()
                .all(|chart| chart.chart_type == ChartType::Line)
        );

        let mixed_workbook = runtime.create_workbook().expect("create mixed chart workbook");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(
                    mixed_workbook.0,
                    "Worksheets",
                    &[OmValue::Number(1.0)],
                )
                .expect("mixed Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("mixed Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(12.0),
                        OmValue::Number(18.0),
                        OmValue::Number(240.0),
                        OmValue::Number(160.0),
                    ],
                )
                .expect("ChartObjects.Add after SetDefaultChart"),
        );
        let embedded_chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("new embedded ChartObject.Chart"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(embedded_chart, "ChartType", &[])
                    .expect("new embedded ChartType")
            ),
            f64::from(super::XL_LINE)
        );

        let charts = expect_object_handle(
            runtime
                .dispatch_get(mixed_workbook.0, "Charts", &[])
                .expect("mixed Workbook.Charts"),
        );
        let chart_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(charts, "Add", &[])
                .expect("Charts.Add after SetDefaultChart"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(chart_sheet, "ChartType", &[])
                    .expect("new chart sheet ChartType")
            ),
            f64::from(super::XL_LINE)
        );

        let saved_mixed_workbook = runtime
            .save_workbook(
                mixed_workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save embedded and chart-sheet defaults");
        let reopened_mixed_workbook = runtime
            .codec
            .load(&saved_mixed_workbook, LoadOptions::default())
            .expect("reopen embedded and chart-sheet defaults");
        assert_eq!(reopened_mixed_workbook.state.charts.len(), 2);
        assert!(
            reopened_mixed_workbook
                .state
                .charts
                .values()
                .all(|chart| chart.chart_type == ChartType::Line)
        );
    }

    #[test]
    fn chart_default_axes_follow_default_chart_family() {
        assert!(super::default_chart_axes_for_type(&ChartType::Pie).is_empty());

        let scatter_axes = super::default_chart_axes_for_type(&ChartType::Scatter);
        assert_eq!(scatter_axes.len(), 2);
        assert!(
            scatter_axes
                .iter()
                .all(|axis| axis.kind == excel_model::ChartAxisKind::Value)
        );
        assert_eq!(scatter_axes[0].cross_axis_raw_id.as_deref(), Some("20"));
        assert_eq!(scatter_axes[1].cross_axis_raw_id.as_deref(), Some("10"));

        let line_axes = super::default_chart_axes_for_type(&ChartType::Line);
        assert_eq!(line_axes.len(), 2);
        assert_eq!(line_axes[0].kind, excel_model::ChartAxisKind::Category);
        assert_eq!(line_axes[1].kind, excel_model::ChartAxisKind::Value);
    }

    #[test]
    fn chart_preserve_only_mutators_mark_workbook_dirty() {
        for (member, args) in [
            ("ClearToMatchColorStyle", Vec::new()),
            (
                "ApplyChartTemplate",
                vec![OmValue::Text("standard.crtx".to_string())],
            ),
            ("ApplyLayout", vec![OmValue::Number(1.0)]),
            (
                "SetBackgroundPicture",
                vec![OmValue::Text("background.png".to_string())],
            ),
        ] {
            let mut runtime = ExcelRuntime::new();
            let workbook = runtime
                .open_workbook(OpenWorkbookSpec {
                    bytes: synthetic_workbook_with_embedded_chart_bytes(),
                    format_hint: Some(FileFormat::Xlsx),
                    profile: ExcelProfile::Excel365,
                    read_only: false,
                })
                .expect("open workbook with chart");
            let worksheet = expect_object_handle(
                runtime
                    .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                    .expect("Workbook.Worksheets(1)"),
            );
            let chart_objects = expect_object_handle(
                runtime
                    .dispatch_get(worksheet, "ChartObjects", &[])
                    .expect("Worksheet.ChartObjects"),
            );
            let chart_object = expect_object_handle(
                runtime
                    .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                    .expect("ChartObjects.Item(1)"),
            );
            let chart = expect_object_handle(
                runtime
                    .dispatch_get(chart_object, "Chart", &[])
                    .expect("ChartObject.Chart"),
            );
            assert_eq!(
                runtime
                    .dispatch_get(workbook.0, "Saved", &[])
                    .expect("Workbook.Saved before chart mutator"),
                OmValue::Bool(true),
                "Workbook.Saved should start clean before Chart.{member}"
            );
            let search_range = expect_object_handle(
                runtime
                    .dispatch_invoke(worksheet, "Range", &[OmValue::Text("A1:B3".to_string())])
                    .expect("Worksheet.Range(A1:B3) before chart mutator"),
            );
            runtime
                .dispatch_invoke(search_range, "Find", &[OmValue::Text("1".to_string())])
                .unwrap_or_else(|error| panic!("Range.Find before Chart.{member}: {error:?}"));
            runtime
                .dispatch_invoke(search_range, "Copy", &[])
                .unwrap_or_else(|error| panic!("Range.Copy before Chart.{member}: {error:?}"));
            assert_eq!(
                expect_number(
                    runtime
                        .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                        .unwrap_or_else(|error| {
                            panic!("Application.CutCopyMode before Chart.{member}: {error:?}")
                        })
                ),
                f64::from(super::XL_COPY),
                "Application.CutCopyMode should be xlCopy before Chart.{member}"
            );

            assert_eq!(
                runtime
                    .dispatch_invoke(chart, member, &args)
                    .unwrap_or_else(|error| panic!("Chart.{member}: {error:?}")),
                OmValue::Empty
            );
            assert_eq!(
                runtime
                    .dispatch_get(workbook.0, "Saved", &[])
                    .expect("Workbook.Saved after chart mutator"),
                OmValue::Bool(false),
                "Chart.{member} should dirty the workbook"
            );
            assert!(
                !expect_bool(
                    runtime
                        .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                        .unwrap_or_else(|error| {
                            panic!("Application.CutCopyMode after Chart.{member}: {error:?}")
                        })
                ),
                "Chart.{member} should clear Application.CutCopyMode"
            );
            assert_eq!(
                match runtime.dispatch_invoke(search_range, "FindNext", &[]) {
                    Ok(value) => panic!("Range.FindNext after Chart.{member} succeeded: {value:?}"),
                    Err(error) => error.code,
                },
                OmErrorCode::InvalidState,
                "Chart.{member} should clear Range.Find state"
            );
        }
    }

    #[test]
    fn embedded_chart_copy_methods_allow_read_only_workbook() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: true,
            })
            .expect("open read-only workbook with embedded chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let chart_area = expect_object_handle(
            runtime
                .dispatch_get(chart, "ChartArea", &[])
                .expect("Chart.ChartArea"),
        );
        let plot_area = expect_object_handle(
            runtime
                .dispatch_get(chart, "PlotArea", &[])
                .expect("Chart.PlotArea"),
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection"),
        );
        let series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("SeriesCollection.Item(1)"),
        );
        let shape_range = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "ShapeRange", &[])
                .expect("ChartObject.ShapeRange"),
        );

        for (handle, member, args) in [
            (chart_object, "Copy", Vec::new()),
            (chart_objects, "Copy", Vec::new()),
            (shape_range, "Copy", Vec::new()),
            (chart, "Copy", Vec::new()),
            (chart_area, "Copy", Vec::new()),
            (
                chart_object,
                "CopyPicture",
                vec![OmValue::Missing, OmValue::Missing],
            ),
            (
                chart_objects,
                "CopyPicture",
                vec![OmValue::Missing, OmValue::Missing],
            ),
            (
                shape_range,
                "CopyPicture",
                vec![OmValue::Missing, OmValue::Missing],
            ),
            (
                chart,
                "CopyPicture",
                vec![OmValue::Missing, OmValue::Missing, OmValue::Missing],
            ),
        ] {
            runtime
                .dispatch_set(
                    runtime.root_application(),
                    "CutCopyMode",
                    OmValue::Bool(false),
                    &[],
                )
                .unwrap_or_else(|error| {
                    panic!("reset Application.CutCopyMode before Chart.{member}: {error:?}")
                });
            assert_eq!(
                runtime
                    .dispatch_invoke(handle, member, &args)
                    .unwrap_or_else(|error| panic!("{member}: {error:?}")),
                OmValue::Empty,
                "{member} should be allowed for read-only workbooks"
            );
            assert_eq!(
                expect_number(
                    runtime
                        .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                        .unwrap_or_else(|error| {
                            panic!("Application.CutCopyMode after Chart.{member}: {error:?}")
                        })
                ),
                f64::from(super::XL_COPY),
                "{member} should set headless copy mode"
            );
            assert!(
                runtime.clipboard.is_none(),
                "{member} should not populate a Range clipboard payload"
            );
            assert_eq!(
                runtime
                    .dispatch_get(workbook.0, "Saved", &[])
                    .expect("Workbook.Saved after read-only copy method"),
                OmValue::Bool(true),
                "{member} should not dirty the read-only workbook"
            );
        }

        assert!(runtime.is_read_only(workbook).expect("source is read-only"));
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(chart_objects, "Count", &[])
                    .expect("ChartObjects.Count after read-only copy methods")
            ),
            1.0
        );
        assert_eq!(
            runtime
                .dispatch_invoke(chart_area, "Select", &[])
                .expect("ChartArea remains live after read-only copy methods"),
            OmValue::Empty
        );
        assert_eq!(
            runtime
                .dispatch_invoke(plot_area, "Select", &[])
                .expect("PlotArea remains live after read-only copy methods"),
            OmValue::Empty
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(series_collection, "Count", &[])
                    .expect("SeriesCollection remains live after read-only copy methods")
            ),
            1.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(series, "PlotOrder", &[])
                    .expect("Series remains live after read-only copy methods")
            ),
            1.0
        );
    }

    #[test]
    fn chart_layout_and_preserve_only_element_mutators_reject_read_only_workbook() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: true,
            })
            .expect("open read-only workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );

        let layout_error = runtime
            .dispatch_invoke(chart, "ApplyLayout", &[OmValue::Number(1.0)])
            .expect_err("Chart.ApplyLayout should reject read-only workbooks");
        assert_eq!(layout_error.code, OmErrorCode::InvalidState);
        assert!(layout_error.message.contains("read-only"));

        let set_element_error = runtime
            .dispatch_invoke(
                chart,
                "SetElement",
                &[OmValue::Number(f64::from(
                    super::MSO_ELEMENT_TRENDLINE_ADD_LINEAR,
                ))],
            )
            .expect_err(
                "Chart.SetElement preserve-only elements should reject read-only workbooks",
            );
        assert_eq!(set_element_error.code, OmErrorCode::InvalidState);
        assert!(set_element_error.message.contains("read-only"));
    }

