    #[test]
    fn loaded_chart_axis_title_setter_preserves_chart_extensions_on_save() {
        let mut package = OpcPackage::from_bytes(&synthetic_workbook_with_embedded_chart_bytes())
            .expect("embedded chart package");
        let chart_xml = String::from_utf8(
            package
                .part("xl/charts/chart1.xml")
                .expect("chart part")
                .bytes
                .clone(),
        )
        .expect("chart xml utf8")
        .replace(
            "</c:chartSpace>",
            r#"<c:extLst><c:ext uri="urn:axis-title-preserve"/></c:extLst></c:chartSpace>"#,
        );
        package
            .replace_part_bytes("xl/charts/chart1.xml", chart_xml.into_bytes())
            .expect("replace chart xml");

        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: package.to_bytes().expect("package bytes"),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let category_axis = expect_object_handle(
            runtime
                .dispatch_get(
                    chart,
                    "Axes",
                    &[OmValue::Number(f64::from(super::XL_CATEGORY))],
                )
                .expect("Chart.Axes(xlCategory)"),
        );
        let axis_title = expect_object_handle(
            runtime
                .dispatch_get(category_axis, "AxisTitle", &[])
                .expect("Axis.AxisTitle"),
        );
        let axis_title_format = expect_object_handle(
            runtime
                .dispatch_get(axis_title, "Format", &[])
                .expect("AxisTitle.Format"),
        );
        assert_eq!(
            runtime
                .dispatch_get(axis_title, "Format", &[OmValue::Missing])
                .expect_err("AxisTitle.Format rejects arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_get(axis_title_format, "Creator", &[])
                .expect("AxisTitle.Format.Creator"),
            OmValue::Number(f64::from(super::XL_CREATOR_CODE))
        );
        assert_eq!(
            runtime
                .dispatch_get(axis_title_format, "AutoShapeType", &[])
                .expect("AxisTitle.Format.AutoShapeType"),
            OmValue::Number(f64::from(super::MSO_SHAPE_MIXED))
        );
        let axis_title_format_parent = expect_object_handle(
            runtime
                .dispatch_get(axis_title_format, "Parent", &[])
                .expect("AxisTitle.Format.Parent"),
        );
        assert_eq!(
            runtime
                .dispatch_get(axis_title_format_parent, "Name", &[])
                .expect("AxisTitle.Format.Parent.Name"),
            OmValue::Text("Axis Title".to_string())
        );
        let search_range = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet, "Range", &[OmValue::Text("A1:B3".to_string())])
                .expect("Worksheet.Range(A1:B3) before AxisTitle.Text"),
        );
        runtime
            .dispatch_invoke(search_range, "Find", &[OmValue::Text("1".to_string())])
            .expect("Range.Find before AxisTitle.Text");
        runtime
            .dispatch_invoke(search_range, "Copy", &[])
            .expect("Range.Copy before AxisTitle.Text");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                    .expect("Application.CutCopyMode before AxisTitle.Text")
            ),
            f64::from(super::XL_COPY)
        );
        runtime
            .dispatch_set(
                axis_title,
                "Text",
                OmValue::Text("Fiscal Quarter".to_string()),
                &[],
            )
            .expect("set loaded AxisTitle.Text");
        assert!(!expect_bool(
            runtime
                .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                .expect("Application.CutCopyMode after AxisTitle.Text")
        ));
        assert_eq!(
            runtime
                .dispatch_invoke(search_range, "FindNext", &[])
                .expect_err("Range.FindNext should require a new Find after AxisTitle.Text")
                .code,
            OmErrorCode::InvalidState
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after loaded axis title edit");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_chart_xml = std::str::from_utf8(
            saved_package
                .part("xl/charts/chart1.xml")
                .expect("saved chart part")
                .bytes
                .as_slice(),
        )
        .expect("saved chart xml utf8");
        assert!(saved_chart_xml.contains(r#"<c:ext uri="urn:axis-title-preserve"/>"#));
        assert!(saved_chart_xml.contains("<a:t>Fiscal Quarter</a:t>"));
        assert!(!saved_chart_xml.contains("<a:t>Quarter</a:t>"));
        assert!(saved_chart_xml.contains("<a:t>Revenue</a:t>"));

        let mut reopened_runtime = ExcelRuntime::new();
        let reopened_workbook = reopened_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen workbook after loaded axis title edit");
        let reopened_worksheet = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("reopened Workbook.Worksheets(1)"),
        );
        let reopened_chart_objects = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_worksheet, "ChartObjects", &[])
                .expect("reopened Worksheet.ChartObjects"),
        );
        let reopened_chart_object = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("reopened ChartObjects.Item(1)"),
        );
        let reopened_chart = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart_object, "Chart", &[])
                .expect("reopened ChartObject.Chart"),
        );
        let reopened_category_axis = expect_object_handle(
            reopened_runtime
                .dispatch_get(
                    reopened_chart,
                    "Axes",
                    &[OmValue::Number(f64::from(super::XL_CATEGORY))],
                )
                .expect("reopened Chart.Axes(xlCategory)"),
        );
        let reopened_axis_title = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_category_axis, "AxisTitle", &[])
                .expect("reopened Axis.AxisTitle"),
        );
        assert_eq!(
            reopened_runtime
                .dispatch_get(reopened_axis_title, "Text", &[])
                .expect("reopened AxisTitle.Text"),
            OmValue::Text("Fiscal Quarter".to_string())
        );
    }

    #[test]
    fn loaded_chart_series_plot_order_setter_preserves_chart_extensions_on_save() {
        let mut package = OpcPackage::from_bytes(&synthetic_workbook_with_embedded_chart_bytes())
            .expect("embedded chart package");
        let chart_xml = String::from_utf8(
            package
                .part("xl/charts/chart1.xml")
                .expect("chart part")
                .bytes
                .clone(),
        )
        .expect("chart xml utf8")
        .replace(
            r#"</c:ser><c:gapWidth val="150"/>"#,
            r#"</c:ser><c:ser><c:idx val="1"/><c:order val="1"/><c:tx><c:strRef><c:f>Sheet1!$C$2</c:f></c:strRef></c:tx><c:cat><c:strRef><c:f>Sheet1!$A$1:$B$1</c:f></c:strRef></c:cat><c:val><c:numRef><c:f>Sheet1!$A$2:$C$2</c:f></c:numRef></c:val></c:ser><c:gapWidth val="150"/>"#,
        )
        .replace(
            "</c:chartSpace>",
            r#"<c:extLst><c:ext uri="urn:series-order-preserve"/></c:extLst></c:chartSpace>"#,
        );
        package
            .replace_part_bytes("xl/charts/chart1.xml", chart_xml.into_bytes())
            .expect("replace chart xml");

        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: package.to_bytes().expect("package bytes"),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with two-series chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(series_collection, "Count", &[])
                    .expect("SeriesCollection.Count")
            ),
            2.0
        );
        let first_series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("SeriesCollection.Item(1)"),
        );
        let second_series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "Item", &[OmValue::Number(2.0)])
                .expect("SeriesCollection.Item(2)"),
        );
        runtime
            .dispatch_set(second_series, "PlotOrder", OmValue::Number(1.0), &[])
            .expect("set loaded second Series.PlotOrder");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_series, "PlotOrder", &[])
                    .expect("first Series.PlotOrder")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_series, "PlotOrder", &[])
                    .expect("second Series.PlotOrder")
            ),
            1.0
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after loaded plot order edit");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_chart_xml = std::str::from_utf8(
            saved_package
                .part("xl/charts/chart1.xml")
                .expect("saved chart part")
                .bytes
                .as_slice(),
        )
        .expect("saved chart xml utf8");
        assert!(saved_chart_xml.contains(r#"<c:ext uri="urn:series-order-preserve"/>"#));
        assert!(saved_chart_xml.contains(r#"<c:idx val="0"/><c:order val="1"/>"#));
        assert!(saved_chart_xml.contains(r#"<c:idx val="1"/><c:order val="0"/>"#));

        let mut reopened_runtime = ExcelRuntime::new();
        let reopened_workbook = reopened_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen workbook after loaded plot order edit");
        let reopened_worksheet = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("reopened Workbook.Worksheets(1)"),
        );
        let reopened_chart_objects = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_worksheet, "ChartObjects", &[])
                .expect("reopened Worksheet.ChartObjects"),
        );
        let reopened_chart_object = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("reopened ChartObjects.Item(1)"),
        );
        let reopened_chart = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart_object, "Chart", &[])
                .expect("reopened ChartObject.Chart"),
        );
        let reopened_series_collection = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart, "SeriesCollection", &[])
                .expect("reopened Chart.SeriesCollection"),
        );
        let reopened_first_series = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("reopened SeriesCollection.Item(1)"),
        );
        let reopened_second_series = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_series_collection, "Item", &[OmValue::Number(2.0)])
                .expect("reopened SeriesCollection.Item(2)"),
        );
        assert_eq!(
            expect_number(
                reopened_runtime
                    .dispatch_get(reopened_first_series, "PlotOrder", &[])
                    .expect("reopened first Series.PlotOrder")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                reopened_runtime
                    .dispatch_get(reopened_second_series, "PlotOrder", &[])
                    .expect("reopened second Series.PlotOrder")
            ),
            1.0
        );
    }

