    #[test]
    fn chart_type_setter_clears_stock_line_flags_for_unsupported_chart_groups() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with embedded chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let chart_group = expect_object_handle(
            runtime
                .dispatch_get(chart, "ChartGroups", &[OmValue::Number(1.0)])
                .expect("Chart.ChartGroups(1)"),
        );

        runtime
            .dispatch_set(
                chart,
                "ChartType",
                OmValue::Number(f64::from(super::XL_STOCK_OHLC)),
                &[],
            )
            .expect("set Chart.ChartType to stock OHLC");
        assert_eq!(
            runtime
                .dispatch_get(chart_group, "HasHiLoLines", &[])
                .expect("ChartGroup.HasHiLoLines for stock chart"),
            OmValue::Bool(true)
        );
        assert_eq!(
            runtime
                .dispatch_get(chart_group, "HasUpDownBars", &[])
                .expect("ChartGroup.HasUpDownBars for stock chart"),
            OmValue::Bool(true)
        );
        let stale_hi_lo_lines = expect_object_handle(
            runtime
                .dispatch_get(chart_group, "HiLoLines", &[])
                .expect("ChartGroup.HiLoLines before bar conversion"),
        );
        let stale_up_bars = expect_object_handle(
            runtime
                .dispatch_get(chart_group, "UpBars", &[])
                .expect("ChartGroup.UpBars before bar conversion"),
        );
        let stale_down_bars = expect_object_handle(
            runtime
                .dispatch_get(chart_group, "DownBars", &[])
                .expect("ChartGroup.DownBars before bar conversion"),
        );

        runtime
            .dispatch_set(
                chart,
                "ChartType",
                OmValue::Number(f64::from(super::XL_BAR_CLUSTERED)),
                &[],
            )
            .expect("set Chart.ChartType away from stock");
        assert_eq!(
            runtime
                .dispatch_get(chart_group, "HasHiLoLines", &[])
                .expect("ChartGroup.HasHiLoLines after bar conversion"),
            OmValue::Bool(false)
        );
        assert_eq!(
            runtime
                .dispatch_get(chart_group, "HasUpDownBars", &[])
                .expect("ChartGroup.HasUpDownBars after bar conversion"),
            OmValue::Bool(false)
        );
        assert_eq!(
            runtime
                .dispatch_get(stale_hi_lo_lines, "Name", &[])
                .expect_err("HiLoLines handle should be stale after bar conversion")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(stale_up_bars, "Name", &[])
                .expect_err("UpBars handle should be stale after bar conversion")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(stale_down_bars, "Name", &[])
                .expect_err("DownBars handle should be stale after bar conversion")
                .code,
            OmErrorCode::InvalidState
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after stock line flag cleanup");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_chart_xml = std::str::from_utf8(
            saved_package
                .part("xl/charts/chart1.xml")
                .expect("saved chart part")
                .bytes
                .as_slice(),
        )
        .expect("saved chart xml utf8");
        assert!(saved_chart_xml.contains("<c:barChart>"));
        assert!(!saved_chart_xml.contains("<c:hiLowLines"));
        assert!(!saved_chart_xml.contains("<c:upDownBars"));

        let mut reopened_runtime = ExcelRuntime::new();
        let reopened_workbook = reopened_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen workbook after stock line flag cleanup");
        let reopened_worksheet = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("reopened Workbook.Worksheets(1)"),
        );
        let reopened_chart_objects = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_worksheet, "ChartObjects", &[])
                .expect("reopened Worksheet.ChartObjects"),
        );
        let reopened_chart_object = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("reopened ChartObjects.Item(1)"),
        );
        let reopened_chart = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart_object, "Chart", &[])
                .expect("reopened ChartObject.Chart"),
        );
        let reopened_chart_group = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart, "ChartGroups", &[OmValue::Number(1.0)])
                .expect("reopened Chart.ChartGroups(1)"),
        );
        assert_eq!(
            reopened_runtime
                .dispatch_get(reopened_chart_group, "HasHiLoLines", &[])
                .expect("reopened ChartGroup.HasHiLoLines after bar conversion"),
            OmValue::Bool(false)
        );
        assert_eq!(
            reopened_runtime
                .dispatch_get(reopened_chart_group, "HasUpDownBars", &[])
                .expect("reopened ChartGroup.HasUpDownBars after bar conversion"),
            OmValue::Bool(false)
        );
    }

