    #[test]
    fn loaded_scatter_chart_type_setter_rewrites_line_source_containers_on_save() {
        let mut package = OpcPackage::from_bytes(&synthetic_workbook_with_embedded_chart_bytes())
            .expect("embedded chart package");
        let chart_xml = String::from_utf8(
            package
                .part("xl/charts/chart1.xml")
                .expect("chart part")
                .bytes
                .clone(),
        )
        .expect("chart xml utf8")
        .replace("<c:barChart>", "<c:scatterChart>")
        .replace("</c:barChart>", "</c:scatterChart>")
        .replace("<c:cat><c:strRef>", "<c:xVal><c:numRef>")
        .replace("</c:strRef></c:cat>", "</c:numRef></c:xVal>")
        .replace("<c:val><c:numRef>", "<c:yVal><c:numRef>")
        .replace("</c:numRef></c:val>", "</c:numRef></c:yVal>")
        .replace(
            "</c:chartSpace>",
            r#"<c:extLst><c:ext uri="urn:chart-type-line-source-preserve"/></c:extLst></c:chartSpace>"#,
        );
        package
            .replace_part_bytes("xl/charts/chart1.xml", chart_xml.into_bytes())
            .expect("replace chart xml");

        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: package.to_bytes().expect("package bytes"),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with scatter chart extension");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        runtime
            .dispatch_set(
                chart,
                "ChartType",
                OmValue::Number(f64::from(super::XL_LINE)),
                &[],
            )
            .expect("set loaded scatter Chart.ChartType to line");

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after loaded line chart type edit");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_chart_xml = std::str::from_utf8(
            saved_package
                .part("xl/charts/chart1.xml")
                .expect("saved chart part")
                .bytes
                .as_slice(),
        )
        .expect("saved chart xml utf8");
        assert!(saved_chart_xml.contains(r#"<c:ext uri="urn:chart-type-line-source-preserve"/>"#));
        assert!(saved_chart_xml.contains("<c:lineChart>"));
        assert!(saved_chart_xml.contains("<c:cat>"));
        assert!(saved_chart_xml.contains("<c:val>"));
        assert!(!saved_chart_xml.contains("<c:xVal>"));
        assert!(!saved_chart_xml.contains("<c:yVal>"));
    }

    #[test]
    fn loaded_chart_has_legend_setter_preserves_chart_extensions_on_save() {
        let mut package = OpcPackage::from_bytes(&synthetic_workbook_with_embedded_chart_bytes())
            .expect("embedded chart package");
        let chart_xml = String::from_utf8(
            package
                .part("xl/charts/chart1.xml")
                .expect("chart part")
                .bytes
                .clone(),
        )
        .expect("chart xml utf8")
        .replace(r#"<c:legend><c:legendPos val="r"/></c:legend>"#, "")
        .replace(
            "</c:chartSpace>",
            r#"<c:extLst><c:ext uri="urn:legend-add-preserve"/></c:extLst></c:chartSpace>"#,
        );
        package
            .replace_part_bytes("xl/charts/chart1.xml", chart_xml.into_bytes())
            .expect("replace chart xml");

        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: package.to_bytes().expect("package bytes"),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook without chart legend");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        assert_eq!(
            runtime
                .dispatch_get(chart, "HasLegend", &[])
                .expect("Chart.HasLegend before set"),
            OmValue::Bool(false)
        );
        let search_range = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet, "Range", &[OmValue::Text("A1:B3".to_string())])
                .expect("Worksheet.Range(A1:B3) before Chart.HasLegend"),
        );
        runtime
            .dispatch_invoke(search_range, "Find", &[OmValue::Text("1".to_string())])
            .expect("Range.Find before Chart.HasLegend");
        runtime
            .dispatch_invoke(search_range, "Copy", &[])
            .expect("Range.Copy before Chart.HasLegend");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                    .expect("Application.CutCopyMode before Chart.HasLegend")
            ),
            f64::from(super::XL_COPY)
        );
        runtime
            .dispatch_set(chart, "HasLegend", OmValue::Bool(true), &[])
            .expect("set loaded Chart.HasLegend");
        assert!(!expect_bool(
            runtime
                .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                .expect("Application.CutCopyMode after Chart.HasLegend")
        ));
        assert_eq!(
            runtime
                .dispatch_invoke(search_range, "FindNext", &[])
                .expect_err("Range.FindNext should require a new Find after Chart.HasLegend")
                .code,
            OmErrorCode::InvalidState
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after loaded legend add");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_chart_xml = std::str::from_utf8(
            saved_package
                .part("xl/charts/chart1.xml")
                .expect("saved chart part")
                .bytes
                .as_slice(),
        )
        .expect("saved chart xml utf8");
        assert!(saved_chart_xml.contains(r#"<c:ext uri="urn:legend-add-preserve"/>"#));
        assert!(saved_chart_xml.contains(r#"<c:legend><c:legendPos val="r"/></c:legend>"#));

        let mut reopened_runtime = ExcelRuntime::new();
        let reopened_workbook = reopened_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen workbook after loaded legend add");
        let reopened_worksheet = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("reopened Workbook.Worksheets(1)"),
        );
        let reopened_chart_objects = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_worksheet, "ChartObjects", &[])
                .expect("reopened Worksheet.ChartObjects"),
        );
        let reopened_chart_object = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("reopened ChartObjects.Item(1)"),
        );
        let reopened_chart = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart_object, "Chart", &[])
                .expect("reopened ChartObject.Chart"),
        );
        assert_eq!(
            reopened_runtime
                .dispatch_get(reopened_chart, "HasLegend", &[])
                .expect("reopened Chart.HasLegend"),
            OmValue::Bool(true)
        );
        let reopened_legend = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart, "Legend", &[])
                .expect("reopened Chart.Legend"),
        );
        assert_eq!(
            expect_number(
                reopened_runtime
                    .dispatch_get(reopened_legend, "Position", &[])
                    .expect("reopened Legend.Position")
            ),
            f64::from(super::XL_LEGEND_POSITION_RIGHT)
        );
    }

