    #[test]
    fn loaded_chart_axis_gridline_setters_preserve_chart_extensions_on_save() {
        let mut package = OpcPackage::from_bytes(&synthetic_workbook_with_embedded_chart_bytes())
            .expect("embedded chart package");
        let chart_xml = String::from_utf8(
            package
                .part("xl/charts/chart1.xml")
                .expect("chart part")
                .bytes
                .clone(),
        )
        .expect("chart xml utf8")
        .replace(
            r#"<c:valAx><c:axId val="20"/><c:title>"#,
            r#"<c:valAx><c:axId val="20"/><c:majorGridlines/><c:title>"#,
        )
        .replace(
            "</c:chartSpace>",
            r#"<c:extLst><c:ext uri="urn:axis-gridlines-preserve"/></c:extLst></c:chartSpace>"#,
        );
        package
            .replace_part_bytes("xl/charts/chart1.xml", chart_xml.into_bytes())
            .expect("replace chart xml");

        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: package.to_bytes().expect("package bytes"),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with value axis gridlines");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let value_axis = expect_object_handle(
            runtime
                .dispatch_get(
                    chart,
                    "Axes",
                    &[OmValue::Number(f64::from(super::XL_VALUE))],
                )
                .expect("Chart.Axes(xlValue)"),
        );
        assert_eq!(
            runtime
                .dispatch_get(value_axis, "HasMajorGridlines", &[])
                .expect("Axis.HasMajorGridlines before set"),
            OmValue::Bool(true)
        );
        assert_eq!(
            runtime
                .dispatch_get(value_axis, "HasMinorGridlines", &[])
                .expect("Axis.HasMinorGridlines before set"),
            OmValue::Bool(false)
        );
        let major_gridlines = expect_object_handle(
            runtime
                .dispatch_get(value_axis, "MajorGridlines", &[])
                .expect("Axis.MajorGridlines"),
        );
        assert_eq!(
            runtime
                .dispatch_get(major_gridlines, "Name", &[])
                .expect("MajorGridlines.Name"),
            OmValue::Text("Major Gridlines".to_string())
        );
        let major_gridlines_format = expect_object_handle(
            runtime
                .dispatch_get(major_gridlines, "Format", &[])
                .expect("MajorGridlines.Format"),
        );
        let major_gridlines_border = expect_object_handle(
            runtime
                .dispatch_get(major_gridlines, "Border", &[])
                .expect("MajorGridlines.Border"),
        );
        assert_eq!(
            runtime
                .dispatch_get(major_gridlines, "Format", &[OmValue::Missing])
                .expect_err("MajorGridlines.Format rejects arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_get(major_gridlines_format, "Creator", &[])
                .expect("MajorGridlines.Format.Creator"),
            OmValue::Number(f64::from(super::XL_CREATOR_CODE))
        );
        assert_eq!(
            runtime
                .dispatch_get(major_gridlines_format, "AutoShapeType", &[])
                .expect("MajorGridlines.Format.AutoShapeType"),
            OmValue::Number(f64::from(super::MSO_SHAPE_MIXED))
        );
        let major_gridlines_format_parent = expect_object_handle(
            runtime
                .dispatch_get(major_gridlines_format, "Parent", &[])
                .expect("MajorGridlines.Format.Parent"),
        );
        assert_eq!(
            runtime
                .dispatch_get(major_gridlines_format_parent, "Name", &[])
                .expect("MajorGridlines.Format.Parent.Name"),
            OmValue::Text("Major Gridlines".to_string())
        );
        assert_eq!(
            runtime
                .dispatch_get(major_gridlines_border, "LineStyle", &[])
                .expect("MajorGridlines.Border.LineStyle"),
            OmValue::Number(f64::from(super::XL_CONTINUOUS))
        );
        let major_gridlines_border_parent = expect_object_handle(
            runtime
                .dispatch_get(major_gridlines_border, "Parent", &[])
                .expect("MajorGridlines.Border.Parent"),
        );
        assert_eq!(
            runtime
                .dispatch_get(major_gridlines_border_parent, "Name", &[])
                .expect("MajorGridlines.Border.Parent.Name"),
            OmValue::Text("Major Gridlines".to_string())
        );
        let major_gridlines_parent = expect_object_handle(
            runtime
                .dispatch_get(major_gridlines, "Parent", &[])
                .expect("MajorGridlines.Parent"),
        );
        assert_eq!(
            runtime
                .dispatch_get(major_gridlines_parent, "Type", &[])
                .expect("MajorGridlines.Parent.Type"),
            OmValue::Number(f64::from(super::XL_VALUE))
        );
        runtime
            .dispatch_invoke(major_gridlines, "Select", &[])
            .expect("MajorGridlines.Select");
        let search_range = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet, "Range", &[OmValue::Text("A1:B3".to_string())])
                .expect("Worksheet.Range(A1:B3) before MajorGridlines.Delete"),
        );
        runtime
            .dispatch_invoke(search_range, "Find", &[OmValue::Text("1".to_string())])
            .expect("Range.Find before MajorGridlines.Delete");
        runtime
            .dispatch_invoke(search_range, "Copy", &[])
            .expect("Range.Copy before MajorGridlines.Delete");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                    .expect("Application.CutCopyMode before MajorGridlines.Delete")
            ),
            f64::from(super::XL_COPY)
        );
        runtime
            .dispatch_invoke(major_gridlines, "Delete", &[])
            .expect("MajorGridlines.Delete");
        assert!(!expect_bool(
            runtime
                .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                .expect("Application.CutCopyMode after MajorGridlines.Delete")
        ));
        assert_eq!(
            runtime
                .dispatch_invoke(search_range, "FindNext", &[])
                .expect_err("Range.FindNext should require a new Find after MajorGridlines.Delete")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(major_gridlines, "Name", &[])
                .expect_err("deleted MajorGridlines handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(major_gridlines_format, "Creator", &[])
                .expect_err("deleted MajorGridlines.Format handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(major_gridlines_border, "LineStyle", &[])
                .expect_err("deleted MajorGridlines.Border handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(value_axis, "MajorGridlines", &[])
                .expect_err("Axis.MajorGridlines after delete")
                .code,
            OmErrorCode::NotFound
        );
        runtime
            .dispatch_invoke(search_range, "Find", &[OmValue::Text("1".to_string())])
            .expect("Range.Find before Axis.HasMinorGridlines");
        runtime
            .dispatch_invoke(search_range, "Copy", &[])
            .expect("Range.Copy before Axis.HasMinorGridlines");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                    .expect("Application.CutCopyMode before Axis.HasMinorGridlines")
            ),
            f64::from(super::XL_COPY)
        );
        runtime
            .dispatch_set(value_axis, "HasMinorGridlines", OmValue::Bool(true), &[])
            .expect("set Axis.HasMinorGridlines");
        assert!(!expect_bool(
            runtime
                .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                .expect("Application.CutCopyMode after Axis.HasMinorGridlines")
        ));
        assert_eq!(
            runtime
                .dispatch_invoke(search_range, "FindNext", &[])
                .expect_err("Range.FindNext should require a new Find after Axis.HasMinorGridlines")
                .code,
            OmErrorCode::InvalidState
        );
        let minor_gridlines = expect_object_handle(
            runtime
                .dispatch_get(value_axis, "MinorGridlines", &[])
                .expect("Axis.MinorGridlines"),
        );
        assert_eq!(
            runtime
                .dispatch_get(minor_gridlines, "Name", &[])
                .expect("MinorGridlines.Name"),
            OmValue::Text("Minor Gridlines".to_string())
        );
        let minor_gridlines_format = expect_object_handle(
            runtime
                .dispatch_get(minor_gridlines, "Format", &[])
                .expect("MinorGridlines.Format"),
        );
        let minor_gridlines_format_parent = expect_object_handle(
            runtime
                .dispatch_get(minor_gridlines_format, "Parent", &[])
                .expect("MinorGridlines.Format.Parent"),
        );
        assert_eq!(
            runtime
                .dispatch_get(minor_gridlines_format_parent, "Name", &[])
                .expect("MinorGridlines.Format.Parent.Name"),
            OmValue::Text("Minor Gridlines".to_string())
        );
        assert_eq!(
            runtime
                .dispatch_set(
                    value_axis,
                    "HasMajorGridlines",
                    OmValue::Text("bad".to_string()),
                    &[]
                )
                .expect_err("Axis.HasMajorGridlines rejects non-bool")
                .code,
            OmErrorCode::TypeMismatch
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after axis gridline edits");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_chart_xml = std::str::from_utf8(
            saved_package
                .part("xl/charts/chart1.xml")
                .expect("saved chart part")
                .bytes
                .as_slice(),
        )
        .expect("saved chart xml utf8");
        assert!(saved_chart_xml.contains(r#"<c:ext uri="urn:axis-gridlines-preserve"/>"#));
        assert!(!saved_chart_xml.contains("<c:majorGridlines"));
        assert!(saved_chart_xml.contains("<c:minorGridlines"));

        let mut reopened_runtime = ExcelRuntime::new();
        let reopened_workbook = reopened_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen workbook after axis gridline edits");
        let reopened_worksheet = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("reopened Workbook.Worksheets(1)"),
        );
        let reopened_chart_objects = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_worksheet, "ChartObjects", &[])
                .expect("reopened Worksheet.ChartObjects"),
        );
        let reopened_chart_object = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("reopened ChartObjects.Item(1)"),
        );
        let reopened_chart = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart_object, "Chart", &[])
                .expect("reopened ChartObject.Chart"),
        );
        let reopened_value_axis = expect_object_handle(
            reopened_runtime
                .dispatch_get(
                    reopened_chart,
                    "Axes",
                    &[OmValue::Number(f64::from(super::XL_VALUE))],
                )
                .expect("reopened Chart.Axes(xlValue)"),
        );
        assert_eq!(
            reopened_runtime
                .dispatch_get(reopened_value_axis, "HasMajorGridlines", &[])
                .expect("reopened Axis.HasMajorGridlines"),
            OmValue::Bool(false)
        );
        assert_eq!(
            reopened_runtime
                .dispatch_get(reopened_value_axis, "HasMinorGridlines", &[])
                .expect("reopened Axis.HasMinorGridlines"),
            OmValue::Bool(true)
        );
    }

