    #[test]
    fn chartobject_delete_preserves_chart_part_when_chart_is_still_referenced() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook with embedded chart");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("ChartObjects.Item(1)"),
        );
        let chart_sheet_id = SheetId(9_999);
        let (chart_id, chart_part_uri, chart_rels_part_uri, had_chart_rels) = {
            let runtime_workbook = runtime
                .runtime_workbook_mut(workbook)
                .expect("runtime workbook");
            let chart_id = runtime_workbook
                .loaded
                .state
                .drawings
                .values()
                .flat_map(|drawing| drawing.objects.iter())
                .find_map(|object| match object {
                    DrawingObjectModel::ChartFrame(chart_object) => Some(chart_object.chart_id),
                    DrawingObjectModel::UnsupportedRaw { .. } => None,
                })
                .expect("embedded chart id");
            let chart_part_uri = runtime_workbook
                .loaded
                .state
                .charts
                .get(&chart_id)
                .expect("chart model")
                .raw_part_uri
                .clone()
                .expect("chart part uri");
            let chart_rels_part_uri = worksheet_relationships_part_uri_for(chart_part_uri.as_str());
            let had_chart_rels = runtime_workbook
                .loaded
                .package
                .contains(chart_rels_part_uri.as_str());
            runtime_workbook.loaded.state.chart_sheets.insert(
                chart_sheet_id,
                ChartSheetBinding {
                    sheet_id: chart_sheet_id,
                    chart_id,
                    drawing_id: None,
                    raw_part_uri: None,
                },
            );
            (
                chart_id,
                chart_part_uri,
                chart_rels_part_uri,
                had_chart_rels,
            )
        };
        let surviving_chart = runtime.register_chart_handle(workbook, chart_id);

        assert_eq!(
            runtime
                .dispatch_invoke(chart_object, "Delete", &[])
                .expect("ChartObject.Delete"),
            OmValue::Bool(true)
        );

        let runtime_workbook = runtime
            .runtime_workbook(workbook)
            .expect("runtime workbook");
        assert!(
            runtime_workbook.loaded.state.charts.contains_key(&chart_id),
            "chart model should remain while a chart sheet still references it"
        );
        assert!(
            runtime_workbook
                .loaded
                .state
                .chart_sheets
                .contains_key(&chart_sheet_id),
            "chart sheet binding should remain"
        );
        assert!(
            runtime_workbook
                .loaded
                .package
                .contains(chart_part_uri.as_str()),
            "shared chart part should remain in the package"
        );
        if had_chart_rels {
            assert!(
                runtime_workbook
                    .loaded
                    .package
                    .contains(chart_rels_part_uri.as_str()),
                "shared chart relationships part should remain in the package"
            );
        }
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(surviving_chart, "ChartType", &[])
                    .expect("surviving Chart handle remains valid")
            ),
            f64::from(super::XL_BAR_CLUSTERED)
        );
    }

    #[test]
    fn chartobjects_delete_removes_unpersisted_embedded_chart_collection() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let first_chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(12.0),
                        OmValue::Number(18.0),
                        OmValue::Number(240.0),
                        OmValue::Number(160.0),
                    ],
                )
                .expect("first ChartObjects.Add"),
        );
        let first_chart = expect_object_handle(
            runtime
                .dispatch_get(first_chart_object, "Chart", &[])
                .expect("first ChartObject.Chart"),
        );
        let first_chart_area = expect_object_handle(
            runtime
                .dispatch_get(first_chart, "ChartArea", &[])
                .expect("first Chart.ChartArea before ChartObjects.Delete"),
        );
        let first_plot_area = expect_object_handle(
            runtime
                .dispatch_get(first_chart, "PlotArea", &[])
                .expect("first Chart.PlotArea before ChartObjects.Delete"),
        );
        let first_series_collection = expect_object_handle(
            runtime
                .dispatch_get(first_chart, "SeriesCollection", &[])
                .expect("first Chart.SeriesCollection before ChartObjects.Delete"),
        );
        runtime
            .dispatch_invoke(
                chart_objects,
                "Add",
                &[
                    OmValue::Number(20.0),
                    OmValue::Number(28.0),
                    OmValue::Number(120.0),
                    OmValue::Number(80.0),
                ],
            )
            .expect("second ChartObjects.Add");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(chart_objects, "Count", &[])
                    .expect("ChartObjects.Count before delete")
            ),
            2.0
        );

        assert_eq!(
            runtime
                .dispatch_invoke(chart_objects, "Delete", &[])
                .expect("ChartObjects.Delete"),
            OmValue::Empty
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(chart_objects, "Count", &[])
                    .expect("ChartObjects.Count after delete")
            ),
            0.0
        );
        assert_eq!(
            runtime
                .dispatch_get(first_chart_object, "Name", &[])
                .expect_err("deleted collection ChartObject handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(first_chart, "ChartType", &[])
                .expect_err("deleted collection Chart handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_invoke(first_chart_area, "Select", &[])
                .expect_err("deleted collection ChartArea handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_invoke(first_plot_area, "Select", &[])
                .expect_err("deleted collection PlotArea handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(first_series_collection, "Count", &[])
                .expect_err("deleted collection SeriesCollection handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after ChartObjects.Delete");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        assert!(!saved_package.contains("xl/charts/chart1.xml"));
        assert!(!saved_package.contains("xl/drawings/drawing1.xml"));
    }

