        assert!(saved_chart_xml.contains(r#"<c:idx val="1"/><c:order val="1"/>"#));
        assert!(saved_chart_xml.contains(r#"<c:axId val="10"/><c:axId val="50"/></c:barChart>"#));

        let mut reopened_runtime = ExcelRuntime::new();
