    #[test]
    fn series_collection_new_series_rebalances_existing_plot_orders() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let worksheet = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("Workbook.Worksheets(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(12.0),
                        OmValue::Number(18.0),
                        OmValue::Number(240.0),
                        OmValue::Number(160.0),
                    ],
                )
                .expect("ChartObjects.Add"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection"),
        );
        let first_series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "NewSeries", &[])
                .expect("SeriesCollection.NewSeries first"),
        );
        let chart_id = match runtime.runtime_object(chart).expect("chart runtime object") {
            super::RuntimeObjectKind::Chart { chart_id, .. } => chart_id,
            other => panic!("expected chart object, got {other:?}"),
        };
        runtime
            .runtime_workbook_mut(workbook)
            .expect("runtime workbook")
            .loaded
            .state
            .charts
            .get_mut(&chart_id)
            .expect("chart model")
            .series[0]
            .order = Some(10);

        let second_series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "NewSeries", &[])
                .expect("SeriesCollection.NewSeries second"),
        );

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(first_series, "PlotOrder", &[])
                    .expect("first Series.PlotOrder")
            ),
            1.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(second_series, "PlotOrder", &[])
                    .expect("second Series.PlotOrder")
            ),
            2.0
        );
        let state = runtime.workbook_state(workbook).expect("workbook state");
        let chart = state.charts.get(&chart_id).expect("chart model");
        assert_eq!(chart.series[0].order, Some(0));
        assert_eq!(chart.series[1].order, Some(1));
    }

    #[test]
    fn chart_series_formula_setter_roundtrips_basic_series_formula() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let worksheet = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("Worksheets.Item(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(12.0),
                        OmValue::Number(18.0),
                        OmValue::Number(240.0),
                        OmValue::Number(160.0),
                    ],
                )
                .expect("ChartObjects.Add"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection"),
        );
        let series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "NewSeries", &[])
                .expect("SeriesCollection.NewSeries"),
        );
        let search_range = expect_object_handle(
            runtime
                .dispatch_invoke(worksheet, "Range", &[OmValue::Text("A1:B3".to_string())])
                .expect("Worksheet.Range(A1:B3) before Series.Formula"),
        );
        runtime
            .dispatch_invoke(search_range, "Find", &[OmValue::Text("1".to_string())])
            .expect("Range.Find before Series.Formula");
        runtime
            .dispatch_invoke(search_range, "Copy", &[])
            .expect("Range.Copy before Series.Formula");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                    .expect("Application.CutCopyMode before Series.Formula")
            ),
            f64::from(super::XL_COPY)
        );
        runtime
            .dispatch_set(
                series,
                "Formula",
                OmValue::Text(
                    "=SERIES(Sheet1!$C$1,Sheet1!$A$1:$A$3,Sheet1!$B$1:$B$3,1)".to_string(),
                ),
                &[],
            )
            .expect("set Series.Formula");
        assert!(!expect_bool(
            runtime
                .dispatch_get(runtime.root_application(), "CutCopyMode", &[])
                .expect("Application.CutCopyMode after Series.Formula")
        ));
        assert_eq!(
            runtime
                .dispatch_invoke(search_range, "FindNext", &[])
                .expect_err("Range.FindNext should require a new Find after Series.Formula")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(series, "Name", &[])
                .expect("Series.Name after Formula"),
            OmValue::Text("=Sheet1!$C$1".to_string())
        );
        assert_eq!(
            runtime
                .dispatch_get(series, "XValues", &[])
                .expect("Series.XValues after Formula"),
            OmValue::Text("=Sheet1!$A$1:$A$3".to_string())
        );
        assert_eq!(
            runtime
                .dispatch_get(series, "Values", &[])
                .expect("Series.Values after Formula"),
            OmValue::Text("=Sheet1!$B$1:$B$3".to_string())
        );
        assert_eq!(
            runtime
                .dispatch_set(
                    series,
                    "Formula",
                    OmValue::Text(
                        "=SERIES(Sheet1!$C$1,Sheet1!$A$1:$A$3,Sheet1!$B$1:$B$3,2)".to_string(),
                    ),
                    &[],
                )
                .expect_err("Series.Formula should reject out-of-bounds plot order")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(series, "Formula", &[])
                    .expect("Series.Formula after rejected plot order")
            ),
            "=SERIES(Sheet1!$C$1,Sheet1!$A$1:$A$3,Sheet1!$B$1:$B$3,1)"
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after Series.Formula");
        let mut reopened_runtime = ExcelRuntime::new();
        let reopened_workbook = reopened_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen workbook after Series.Formula");
        let reopened_worksheets = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_workbook.0, "Worksheets", &[])
                .expect("reopened Workbook.Worksheets"),
        );
        let reopened_worksheet = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("reopened Worksheets.Item(1)"),
        );
        let reopened_chart_objects = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_worksheet, "ChartObjects", &[])
                .expect("reopened Worksheet.ChartObjects"),
        );
        let reopened_chart_object = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_chart_objects, "Item", &[OmValue::Number(1.0)])
                .expect("reopened ChartObjects.Item(1)"),
        );
        let reopened_chart = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart_object, "Chart", &[])
                .expect("reopened ChartObject.Chart"),
        );
        let reopened_series_collection = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_chart, "SeriesCollection", &[])
                .expect("reopened Chart.SeriesCollection"),
        );
        let reopened_series = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_series_collection, "Item", &[OmValue::Number(1.0)])
                .expect("reopened SeriesCollection.Item(1)"),
        );
        assert_eq!(
            expect_text(
                reopened_runtime
                    .dispatch_get(reopened_series, "Formula", &[])
                    .expect("reopened Series.Formula")
            ),
            "=SERIES(Sheet1!$C$1,Sheet1!$A$1:$A$3,Sheet1!$B$1:$B$3,1)"
        );
    }

    #[test]
    fn chart_series_formula_setter_preserves_external_sources() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let worksheet = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("Worksheets.Item(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(12.0),
                        OmValue::Number(18.0),
                        OmValue::Number(240.0),
                        OmValue::Number(160.0),
                    ],
                )
                .expect("ChartObjects.Add"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection"),
        );
        let series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "NewSeries", &[])
                .expect("SeriesCollection.NewSeries"),
        );
        let formula = "=SERIES('[Other.xlsx]Data 2026'!$C$1,'[Other.xlsx]Data 2026'!$A$1:$A$3,'[Other.xlsx]Data 2026'!$B$1:$B$3,1)";
        runtime
            .dispatch_set(series, "Formula", OmValue::Text(formula.to_string()), &[])
            .expect("set external Series.Formula");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(series, "Formula", &[])
                    .expect("Series.Formula after external setter")
            ),
            formula
        );
        assert_eq!(
            runtime
                .dispatch_get(series, "Values", &[])
                .expect("Series.Values after external Formula"),
            OmValue::Text("='[Other.xlsx]Data 2026'!$B$1:$B$3".to_string())
        );
        {
            let state = runtime.workbook_state(workbook).expect("workbook state");
            let chart = state.charts.values().next().expect("chart model");
            let values = chart.series[0].values.as_ref().expect("series values");
            let Some(ReferenceTarget::External(external)) = values.resolved.as_ref() else {
                panic!("external formula values should resolve to an external reference");
            };
            assert_eq!(external.text, "'[Other.xlsx]Data 2026'!$B$1:$B$3");
        }
        runtime
            .dispatch_set(
                worksheet,
                "Name",
                OmValue::Text("Local Data".to_string()),
                &[],
            )
            .expect("rename local sheet after external Series.Formula");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(series, "Formula", &[])
                    .expect("Series.Formula after local sheet rename")
            ),
            formula
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after external Series.Formula");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_chart_xml = String::from_utf8(
            saved_package
                .part("xl/charts/chart1.xml")
                .expect("saved chart part")
                .bytes
                .clone(),
        )
        .expect("saved chart xml utf8");
        assert!(saved_chart_xml.contains("<c:f>'[Other.xlsx]Data 2026'!$B$1:$B$3</c:f>"));
        assert!(!saved_chart_xml.contains("Local Data"));

        let mut reopened_runtime = ExcelRuntime::new();
        let reopened_workbook = reopened_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen workbook after external Series.Formula");
        let reopened_state = reopened_runtime
            .workbook_state(reopened_workbook)
            .expect("reopened workbook state");
        let reopened_chart = reopened_state
            .charts
            .values()
            .next()
            .expect("reopened chart");
        let reopened_values = reopened_chart.series[0]
            .values
            .as_ref()
            .expect("reopened values");
        let Some(ReferenceTarget::External(reopened_external)) = reopened_values.resolved.as_ref()
        else {
            panic!("reopened external formula values should resolve to an external reference");
        };
        assert_eq!(reopened_external.text, "'[Other.xlsx]Data 2026'!$B$1:$B$3");
    }

    #[test]
    fn chart_series_formula_setter_resolves_defined_name_sources() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let worksheet = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("Worksheets.Item(1)"),
        );
        let chart_objects = expect_object_handle(
            runtime
                .dispatch_get(worksheet, "ChartObjects", &[])
                .expect("Worksheet.ChartObjects"),
        );
        let chart_object = expect_object_handle(
            runtime
                .dispatch_invoke(
                    chart_objects,
                    "Add",
                    &[
                        OmValue::Number(12.0),
                        OmValue::Number(18.0),
                        OmValue::Number(240.0),
                        OmValue::Number(160.0),
                    ],
                )
                .expect("ChartObjects.Add"),
        );
        let chart = expect_object_handle(
            runtime
                .dispatch_get(chart_object, "Chart", &[])
                .expect("ChartObject.Chart"),
        );
        let series_collection = expect_object_handle(
            runtime
                .dispatch_get(chart, "SeriesCollection", &[])
                .expect("Chart.SeriesCollection"),
        );
        let series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "NewSeries", &[])
                .expect("SeriesCollection.NewSeries"),
        );
        let r1c1_series = expect_object_handle(
            runtime
                .dispatch_invoke(series_collection, "NewSeries", &[])
                .expect("SeriesCollection.NewSeries R1C1"),
        );
        let names = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Names", &[])
                .expect("Workbook.Names"),
        );
        let name = expect_object_handle(
            runtime
                .dispatch_invoke(
                    names,
                    "Add",
                    &[
                        OmValue::Text("SeriesValues".to_string()),
                        OmValue::Text("=Sheet1!$B$1:$B$3".to_string()),
                    ],
                )
                .expect("Names.Add SeriesValues"),
        );
        runtime
            .dispatch_invoke(
                names,
                "Add",
                &[
                    OmValue::Text("R1C1SeriesValues".to_string()),
                    OmValue::Missing,
                    OmValue::Missing,
                    OmValue::Missing,
                    OmValue::Missing,
                    OmValue::Missing,
                    OmValue::Missing,
                    OmValue::Missing,
                    OmValue::Missing,
                    OmValue::Text("=Sheet1!R1C4:R3C4".to_string()),
                ],
            )
            .expect("Names.Add R1C1SeriesValues");

        runtime
            .dispatch_set(
                series,
                "Formula",
                OmValue::Text("=SERIES(,,SeriesValues,1)".to_string()),
                &[],
            )
            .expect("set Series.Formula from defined name");
        runtime
            .dispatch_set(
                r1c1_series,
                "Formula",
                OmValue::Text("=SERIES(,,R1C1SeriesValues,2)".to_string()),
                &[],
            )
            .expect("set Series.Formula from R1C1 defined name");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(series, "Formula", &[])
                    .expect("Series.Formula after defined-name setter")
            ),
            "=SERIES(,,SeriesValues,1)"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(r1c1_series, "Formula", &[])
                    .expect("R1C1 Series.Formula after defined-name setter")
            ),
            "=SERIES(,,R1C1SeriesValues,2)"
        );
        {
            let state = runtime
                .workbook_state(workbook)
                .expect("workbook state after formula setter");
            let chart = state.charts.values().next().expect("chart model");
            let values = chart.series[0].values.as_ref().expect("series values");
            assert_eq!(values.raw.text, "SeriesValues");
            let Some(ReferenceTarget::Range(range)) = values.resolved.as_ref() else {
                panic!("Series.Formula defined-name values should resolve to a range");
            };
            assert_eq!(range.areas()[0].rect.col_first, 2);
            assert_eq!(range.areas()[0].rect.col_last, 2);

            let r1c1_values = chart.series[1].values.as_ref().expect("R1C1 series values");
            assert_eq!(r1c1_values.raw.text, "R1C1SeriesValues");
            let Some(ReferenceTarget::Range(r1c1_range)) = r1c1_values.resolved.as_ref() else {
                panic!("Series.Formula R1C1 defined-name values should resolve to a range");
            };
            assert_eq!(r1c1_range.areas()[0].rect.col_first, 4);
            assert_eq!(r1c1_range.areas()[0].rect.col_last, 4);
        }

        runtime
            .dispatch_set(
                name,
                "RefersTo",
                OmValue::Text("=Sheet1!$C$1:$C$3".to_string()),
                &[],
            )
            .expect("set Name.RefersTo");
        {
            let state = runtime
                .workbook_state(workbook)
                .expect("workbook state after RefersTo update");
            let chart = state.charts.values().next().expect("chart model");
            let values = chart.series[0].values.as_ref().expect("series values");
            assert_eq!(values.raw.text, "SeriesValues");
            let Some(ReferenceTarget::Range(range)) = values.resolved.as_ref() else {
                panic!("Series.Formula defined-name values should refresh after RefersTo");
            };
            assert_eq!(range.areas()[0].rect.col_first, 3);
            assert_eq!(range.areas()[0].rect.col_last, 3);
        }

        runtime
            .dispatch_set(
                worksheet,
                "Name",
                OmValue::Text("Data 2026".to_string()),
                &[],
            )
            .expect("rename worksheet with Series.Formula defined names");
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(series, "Formula", &[])
                    .expect("Series.Formula after worksheet rename")
            ),
            "=SERIES(,,SeriesValues,1)"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(r1c1_series, "Formula", &[])
                    .expect("R1C1 Series.Formula after worksheet rename")
            ),
            "=SERIES(,,R1C1SeriesValues,2)"
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after Series.Formula defined names");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_workbook_xml = String::from_utf8(
            saved_package
                .part("xl/workbook.xml")
                .expect("saved workbook part")
                .bytes
                .clone(),
        )
        .expect("saved workbook xml utf8");
        let saved_chart_xml = String::from_utf8(
            saved_package
                .part("xl/charts/chart1.xml")
                .expect("saved chart part")
                .bytes
                .clone(),
        )
        .expect("saved chart xml utf8");
        assert!(
            saved_workbook_xml.contains(
                r#"<definedName name="SeriesValues">'Data 2026'!$C$1:$C$3</definedName>"#
            )
        );
        assert!(saved_workbook_xml.contains(
            r#"<definedName name="R1C1SeriesValues">'Data 2026'!R1C4:R3C4</definedName>"#
        ));
        assert!(saved_chart_xml.contains("<c:f>SeriesValues</c:f>"));
        assert!(saved_chart_xml.contains("<c:f>R1C1SeriesValues</c:f>"));
        assert!(!saved_chart_xml.contains("<c:f>'Data 2026'!$C$1:$C$3</c:f>"));
        assert!(!saved_chart_xml.contains("<c:f>'Data 2026'!R1C4:R3C4</c:f>"));
    }

