    #[test]
    fn pivot_worksheet_collection_lifecycle_is_rejected_before_mutation() {
        for operation in ["Copy", "Move"] {
            let mut runtime = ExcelRuntime::new();
            let workbook = open_synthetic_pivot_workbook(&mut runtime);
            let application = runtime.root_application();
            let workbooks = expect_object_handle(
                runtime
                    .dispatch_get(application, "Workbooks", &[])
                    .expect("Application.Workbooks"),
            );
            let worksheets = expect_object_handle(
                runtime
                    .dispatch_get(workbook.0, "Worksheets", &[])
                    .expect("pivot Workbook.Worksheets"),
            );
            let before = runtime_workbook_persistence_snapshot(&runtime, workbook);
            let before_created_index = runtime.next_created_workbook_index;

            let error = match runtime.dispatch_invoke(worksheets, operation, &[]) {
                Ok(_) => panic!("Worksheets.{operation} on pivot workbook must fail"),
                Err(error) => error,
            };

            assert_eq!(error.code, OmErrorCode::Unsupported, "{operation}");
            assert_eq!(runtime.next_created_workbook_index, before_created_index);
            assert_eq!(
                expect_number(
                    runtime
                        .dispatch_get(workbooks, "Count", &[])
                        .expect("Workbooks.Count after rejected collection operation")
                ),
                1.0,
                "{operation}",
            );
            assert_eq!(
                runtime_workbook_persistence_snapshot(&runtime, workbook),
                before,
                "{operation}",
            );
        }

        let mut runtime = ExcelRuntime::new();
        let workbook = open_synthetic_pivot_workbook(&mut runtime);
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("pivot Workbook.Worksheets"),
        );
        let before = runtime_workbook_persistence_snapshot(&runtime, workbook);

        let error = runtime
            .dispatch_invoke(worksheets, "Delete", &[])
            .expect_err("Worksheets.Delete on pivot workbook must fail");

        assert_eq!(error.code, OmErrorCode::Unsupported);
        assert_eq!(runtime_workbook_persistence_snapshot(&runtime, workbook), before);
    }

    #[test]
    fn worksheet_delete_removes_sheet_updates_selection_and_persists_on_save() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let sheet2 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Add", &[])
                .expect("Worksheets.Add Sheet2"),
        );
        let sheet3 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Add", &[])
                .expect("Worksheets.Add Sheet3"),
        );
        let range_b2 = expect_object_handle(
            runtime
                .dispatch_invoke(sheet3, "Range", &[OmValue::Text("B2".to_string())])
                .expect("Sheet3.Range(B2)"),
        );

        assert!(!expect_bool(
            runtime
                .dispatch_invoke(sheet3, "Delete", &[])
                .expect("Worksheet.Delete with DisplayAlerts=true")
        ));
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(worksheets, "Count", &[])
                    .expect("Worksheets.Count after canceled delete")
            ),
            3.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(sheet3, "Name", &[])
                    .expect("Sheet3 should remain after canceled delete")
            ),
            "Sheet3"
        );
        runtime
            .dispatch_set(application, "DisplayAlerts", OmValue::Bool(false), &[])
            .expect("Application.DisplayAlerts = false");
        let search_range = expect_object_handle(
            runtime
                .dispatch_invoke(sheet2, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Sheet2.Range(A1) before Worksheet.Delete"),
        );
        runtime
            .dispatch_set(
                search_range,
                "Value",
                OmValue::Text("delete needle".to_string()),
                &[],
            )
            .expect("seed Range.Find value before Worksheet.Delete");
        runtime
            .dispatch_invoke(search_range, "Copy", &[])
            .expect("Range.Copy before Worksheet.Delete");
        runtime
            .dispatch_invoke(
                search_range,
                "Find",
                &[OmValue::Text("delete needle".to_string())],
            )
            .expect("Range.Find before Worksheet.Delete");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(application, "CutCopyMode", &[])
                    .expect("Application.CutCopyMode before Worksheet.Delete")
            ),
            f64::from(super::XL_COPY)
        );

        assert!(expect_bool(
            runtime
                .dispatch_invoke(sheet3, "Delete", &[])
                .expect("Worksheet.Delete with DisplayAlerts=false")
        ));
        assert!(!expect_bool(
            runtime
                .dispatch_get(application, "CutCopyMode", &[])
                .expect("Application.CutCopyMode after Worksheet.Delete")
        ));
        assert_eq!(
            runtime
                .dispatch_invoke(search_range, "FindNext", &[])
                .expect_err("Range.FindNext should require a new Find after Worksheet.Delete")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(worksheets, "Count", &[])
                    .expect("Worksheets.Count after delete")
            ),
            2.0
        );
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet after delete"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_sheet, "Name", &[])
                    .expect("ActiveSheet name after delete")
            ),
            "Sheet2"
        );
        let active_cell = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveCell", &[])
                .expect("ActiveCell after delete"),
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_cell, "Address", &[])
                    .expect("ActiveCell address after delete")
            ),
            "$A$1"
        );
        assert_eq!(
            runtime
                .dispatch_get(sheet3, "Name", &[])
                .expect_err("deleted worksheet handle should become stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(range_b2, "Address", &[])
                .expect_err("ranges on deleted worksheets should become stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_invoke(worksheets, "Item", &[OmValue::Text("Sheet3".to_string())])
                .expect_err("deleted worksheet should no longer resolve by name")
                .code,
            OmErrorCode::NotFound
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved workbook package");
        let reopened = ExcelRuntime::new()
            .codec
            .load(&saved, LoadOptions::default())
            .expect("reopen saved workbook");

        assert!(!saved_package.contains("xl/worksheets/sheet3.xml"));
        assert_eq!(
            reopened
                .state
                .worksheets
                .iter()
                .map(|worksheet| worksheet.name.clone())
                .collect::<Vec<_>>(),
            vec!["Sheet2".to_string(), "Sheet1".to_string()]
        );
    }

    #[test]
    fn worksheet_delete_removes_native_macro_and_dialog_sheet_package_parts() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let sheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Sheets", &[])
                .expect("Workbook.Sheets"),
        );
        let macro_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(
                    worksheets,
                    "Add",
                    &[
                        OmValue::Missing,
                        OmValue::Number(1.0),
                        OmValue::Missing,
                        OmValue::Number(f64::from(super::XL_SHEET_TYPE_EXCEL4_MACRO_SHEET)),
                    ],
                )
                .expect("Worksheets.Add Type:=xlExcel4MacroSheet"),
        );
        let dialog_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(
                    worksheets,
                    "Add",
                    &[
                        OmValue::Missing,
                        OmValue::Number(2.0),
                        OmValue::Missing,
                        OmValue::Number(f64::from(super::XL_SHEET_TYPE_DIALOG_SHEET)),
                    ],
                )
                .expect("Worksheets.Add Type:=xlDialogSheet"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(sheets, "Count", &[])
                    .expect("Sheets.Count before delete")
            ),
            3.0
        );
        runtime
            .dispatch_set(application, "DisplayAlerts", OmValue::Bool(false), &[])
            .expect("Application.DisplayAlerts = false");

        assert!(expect_bool(
            runtime
                .dispatch_invoke(dialog_sheet, "Delete", &[])
                .expect("delete dialog sheet")
        ));
        assert!(expect_bool(
            runtime
                .dispatch_invoke(macro_sheet, "Delete", &[])
                .expect("delete macro sheet")
        ));
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(sheets, "Count", &[])
                    .expect("Sheets.Count after delete")
            ),
            1.0
        );
        assert_eq!(
            runtime
                .dispatch_get(dialog_sheet, "Name", &[])
                .expect_err("deleted dialog sheet handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            runtime
                .dispatch_get(macro_sheet, "Name", &[])
                .expect_err("deleted macro sheet handle should be stale")
                .code,
            OmErrorCode::InvalidState
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook after native sheet deletes");
        let saved_package =
            OpcPackage::from_bytes(&saved).expect("saved native sheet delete package");
        let saved_content_types = std::str::from_utf8(
            saved_package
                .part(super::CONTENT_TYPES_PART_NAME)
                .expect("saved content types")
                .bytes
                .as_slice(),
        )
        .expect("saved content types utf8");
        let saved_workbook_rels = std::str::from_utf8(
            saved_package
                .part(super::WORKBOOK_RELS_PART_NAME)
                .expect("saved workbook relationships")
                .bytes
                .as_slice(),
        )
        .expect("saved workbook rels utf8");
        let reopened = ExcelRuntime::new()
            .codec
            .load(&saved, LoadOptions::default())
            .expect("reopen saved workbook");

        assert!(!saved_package.contains("xl/macrosheets/sheet1.xml"));
        assert!(!saved_package.contains("xl/macrosheets/_rels/sheet1.xml.rels"));
        assert!(!saved_package.contains("xl/dialogsheets/sheet1.xml"));
        assert!(!saved_package.contains("xl/dialogsheets/_rels/sheet1.xml.rels"));
        assert!(!saved_content_types.contains("/xl/macrosheets/sheet1.xml"));
        assert!(!saved_content_types.contains("/xl/dialogsheets/sheet1.xml"));
        assert!(!saved_workbook_rels.contains("xlMacrosheet"));
        assert!(!saved_workbook_rels.contains("relationships/dialogsheet"));
        assert_eq!(
            reopened
                .state
                .worksheets
                .iter()
                .map(|worksheet| (worksheet.name.clone(), worksheet.kind))
                .collect::<Vec<_>>(),
            vec![("Sheet1".to_string(), office_common::SheetKind::Worksheet)]
        );
    }

    #[test]
    fn worksheet_delete_rejects_last_sheet_read_only_and_extra_arguments() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let last_sheet_error = runtime
            .dispatch_invoke(sheet, "Delete", &[])
            .expect_err("Worksheet.Delete should reject deleting the last sheet");
        assert_eq!(last_sheet_error.code, OmErrorCode::InvalidState);
        assert!(last_sheet_error.message.contains("last worksheet"));

        let arg_error = runtime
            .dispatch_invoke(sheet, "Delete", &[OmValue::Bool(true)])
            .expect_err("Worksheet.Delete should reject arguments");
        assert_eq!(arg_error.code, OmErrorCode::InvalidArgument);

        let mut read_only_runtime = ExcelRuntime::new();
        let _read_only_workbook = read_only_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: true,
            })
            .expect("open read-only workbook");
        let read_only_sheet = expect_object_handle(
            read_only_runtime
                .dispatch_get(read_only_runtime.root_application(), "ActiveSheet", &[])
                .expect("read-only ActiveSheet"),
        );
        let read_only_error = read_only_runtime
            .dispatch_invoke(read_only_sheet, "Delete", &[])
            .expect_err("Worksheet.Delete should reject read-only workbooks");
        assert_eq!(read_only_error.code, OmErrorCode::InvalidState);
        assert!(read_only_error.message.contains("read-only"));
    }

