    #[test]
    fn worksheet_copy_supports_same_workbook_placement_targets() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let sheet2 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Add", &[])
                .expect("Worksheets.Add Sheet2"),
        );
        let source_range = expect_object_handle(
            runtime
                .dispatch_invoke(sheet2, "Range", &[OmValue::Text("C3".to_string())])
                .expect("Sheet2.Range(C3)"),
        );
        runtime
            .dispatch_set(
                source_range,
                "Value",
                OmValue::Text("copied".to_string()),
                &[],
            )
            .expect("Sheet2.Range(C3).Value");
        runtime
            .dispatch_invoke(source_range, "Copy", &[])
            .expect("Range.Copy before Worksheet.Copy");
        runtime
            .dispatch_invoke(source_range, "Find", &[OmValue::Text("copied".to_string())])
            .expect("Range.Find before Worksheet.Copy");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(application, "CutCopyMode", &[])
                    .expect("Application.CutCopyMode before Worksheet.Copy")
            ),
            f64::from(super::XL_COPY)
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(sheet2, "Copy", &[OmValue::Missing, OmValue::Number(2.0)])
                .expect("Worksheet.Copy After:=2"),
            OmValue::Empty
        ));
        assert!(!expect_bool(
            runtime
                .dispatch_get(application, "CutCopyMode", &[])
                .expect("Application.CutCopyMode after Worksheet.Copy")
        ));
        assert_eq!(
            runtime
                .dispatch_invoke(source_range, "FindNext", &[])
                .expect_err("Range.FindNext should require a new Find after Worksheet.Copy")
                .code,
            OmErrorCode::InvalidState
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(worksheets, "Count", &[])
                    .expect("Worksheets.Count after placement copy")
            ),
            3.0
        );
        let copied_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(
                    worksheets,
                    "Item",
                    &[OmValue::Text("Sheet2 (2)".to_string())],
                )
                .expect("Worksheets.Item(Sheet2 (2))"),
        );
        let copied_range = expect_object_handle(
            runtime
                .dispatch_invoke(copied_sheet, "Range", &[OmValue::Text("C3".to_string())])
                .expect("Sheet2 (2).Range(C3)"),
        );
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet after placement copy"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(active_sheet, "Name", &[])
                    .expect("ActiveSheet.Name after placement copy")
            ),
            "Sheet2 (2)"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(copied_range, "Value", &[])
                    .expect("copied sheet C3 value")
            ),
            "copied"
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook");
        let reopened = ExcelRuntime::new()
            .codec
            .load(&saved, LoadOptions::default())
            .expect("reopen copied workbook");

        assert_eq!(
            reopened
                .state
                .worksheets
                .iter()
                .map(|worksheet| worksheet.name.clone())
                .collect::<Vec<_>>(),
            vec![
                "Sheet2".to_string(),
                "Sheet1".to_string(),
                "Sheet2 (2)".to_string()
            ]
        );
        assert_eq!(
            reopened
                .state
                .cell(reopened.state.worksheets[2].id, 3, 3)
                .map(|cell| cell.value.clone()),
            Some(CellValue::Text("copied".to_string()))
        );
    }

    #[test]
    fn worksheet_copy_preserves_shared_string_values_with_existing_target_table() {
        let mut runtime = ExcelRuntime::new();
        let source_workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open source workbook");
        let mut target_package =
            OpcPackage::from_bytes(&synthetic_workbook_bytes()).expect("target package");
        target_package
            .replace_part_bytes(
                super::SHARED_STRINGS_PART_NAME,
                br#"<?xml version="1.0" encoding="UTF-8"?>
<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
  <si><t>target-only</t></si>
</sst>"#
                    .to_vec(),
            )
            .expect("replace target shared strings");
        let target_workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: target_package.to_bytes().expect("target workbook bytes"),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open target workbook");
        let source_worksheets = expect_object_handle(
            runtime
                .dispatch_get(source_workbook.0, "Worksheets", &[])
                .expect("source Workbook.Worksheets"),
        );
        let target_worksheets = expect_object_handle(
            runtime
                .dispatch_get(target_workbook.0, "Worksheets", &[])
                .expect("target Workbook.Worksheets"),
        );
        let source_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(source_worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("source Worksheets.Item(1)"),
        );
        let target_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(target_worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("target Worksheets.Item(1)"),
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(
                    source_sheet,
                    "Copy",
                    &[OmValue::Missing, OmValue::Object(target_sheet)]
                )
                .expect("source Worksheet.Copy After:=target sheet"),
            OmValue::Empty
        ));
        let saved = runtime
            .save_workbook(
                target_workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save target workbook after Worksheet.Copy");
        let reopened = ExcelRuntime::new()
            .codec
            .load(&saved, LoadOptions::default())
            .expect("reopen target workbook after Worksheet.Copy");
        let original_sheet = reopened
            .state
            .worksheets
            .iter()
            .find(|worksheet| worksheet.name == "Sheet1")
            .expect("original target Sheet1");
        let copied_sheet = reopened
            .state
            .worksheets
            .iter()
            .find(|worksheet| worksheet.name == "Sheet1 (2)")
            .expect("copied source Sheet1");

        assert_eq!(
            reopened
                .state
                .cell(original_sheet.id, 1, 3)
                .map(|cell| cell.value.clone()),
            Some(CellValue::Text("target-only".to_string()))
        );
        assert_eq!(
            reopened
                .state
                .cell(copied_sheet.id, 1, 3)
                .map(|cell| cell.value.clone()),
            Some(CellValue::Text("shared".to_string()))
        );
    }

    #[test]
    fn worksheet_copy_preserves_native_macro_and_dialog_sheet_kinds_for_placement_copy() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let sheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Sheets", &[])
                .expect("Workbook.Sheets"),
        );
        let macro_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(
                    worksheets,
                    "Add",
                    &[
                        OmValue::Missing,
                        OmValue::Number(1.0),
                        OmValue::Missing,
                        OmValue::Number(f64::from(super::XL_SHEET_TYPE_EXCEL4_MACRO_SHEET)),
                    ],
                )
                .expect("Worksheets.Add Type:=xlExcel4MacroSheet"),
        );
        let dialog_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(
                    worksheets,
                    "Add",
                    &[
                        OmValue::Missing,
                        OmValue::Number(2.0),
                        OmValue::Missing,
                        OmValue::Number(f64::from(super::XL_SHEET_TYPE_DIALOG_SHEET)),
                    ],
                )
                .expect("Worksheets.Add Type:=xlDialogSheet"),
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(
                    macro_sheet,
                    "Copy",
                    &[OmValue::Missing, OmValue::Object(dialog_sheet)]
                )
                .expect("copy macro sheet after dialog sheet"),
            OmValue::Empty
        ));
        let copied_macro_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(sheets, "Item", &[OmValue::Text("Macro1 (2)".to_string())])
                .expect("Sheets.Item(Macro1 (2))"),
        );
        assert!(matches!(
            runtime
                .dispatch_invoke(
                    dialog_sheet,
                    "Copy",
                    &[OmValue::Missing, OmValue::Object(copied_macro_sheet)]
                )
                .expect("copy dialog sheet after copied macro sheet"),
            OmValue::Empty
        ));

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        assert!(saved_package.contains("xl/macrosheets/sheet1.xml"));
        assert!(saved_package.contains("xl/macrosheets/sheet2.xml"));
        assert!(saved_package.contains("xl/dialogsheets/sheet1.xml"));
        assert!(saved_package.contains("xl/dialogsheets/sheet2.xml"));
        let saved_content_types = std::str::from_utf8(
            saved_package
                .part(super::CONTENT_TYPES_PART_NAME)
                .expect("saved content types")
                .bytes
                .as_slice(),
        )
        .expect("saved content types utf8");
        assert!(saved_content_types.contains(
            r#"PartName="/xl/macrosheets/sheet2.xml" ContentType="application/vnd.ms-excel.macrosheet+xml""#
        ));
        assert!(saved_content_types.contains(
            r#"PartName="/xl/dialogsheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.dialogsheet+xml""#
        ));
        let saved_workbook_rels = std::str::from_utf8(
            saved_package
                .part(super::WORKBOOK_RELS_PART_NAME)
                .expect("saved workbook relationships")
                .bytes
                .as_slice(),
        )
        .expect("saved workbook rels utf8");
        assert!(saved_workbook_rels.contains(
            r#"Type="http://schemas.microsoft.com/office/2006/relationships/xlMacrosheet" Target="macrosheets/sheet2.xml""#
        ));
        assert!(saved_workbook_rels.contains(
            r#"Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/dialogsheet" Target="dialogsheets/sheet2.xml""#
        ));

        let reopened = ExcelRuntime::new()
            .codec
            .load(&saved, LoadOptions::default())
            .expect("reopen workbook");
        assert_eq!(
            reopened
                .state
                .worksheets
                .iter()
                .map(|worksheet| worksheet.name.clone())
                .collect::<Vec<_>>(),
            vec![
                "Sheet1".to_string(),
                "Macro1".to_string(),
                "Dialog1".to_string(),
                "Macro1 (2)".to_string(),
                "Dialog1 (2)".to_string()
            ]
        );
        for (name, kind, part_uri) in [
            (
                "Macro1",
                office_common::SheetKind::MacroSheet,
                "xl/macrosheets/sheet1.xml",
            ),
            (
                "Dialog1",
                office_common::SheetKind::DialogSheet,
                "xl/dialogsheets/sheet1.xml",
            ),
            (
                "Macro1 (2)",
                office_common::SheetKind::MacroSheet,
                "xl/macrosheets/sheet2.xml",
            ),
            (
                "Dialog1 (2)",
                office_common::SheetKind::DialogSheet,
                "xl/dialogsheets/sheet2.xml",
            ),
        ] {
            let sheet = reopened
                .state
                .worksheets
                .iter()
                .find(|worksheet| worksheet.name == name)
                .expect("reopened copied native sheet");
            assert_eq!(sheet.kind, kind);
            assert_eq!(sheet.part_uri.as_deref(), Some(part_uri));
        }
    }

