    #[test]
    fn worksheet_copy_rejects_dangling_chart_relationship_graph_atomically() {
        let mut runtime = ExcelRuntime::new();
        let source_workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_relationship_graph_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open worksheet chart relationship graph source");
        assert!(
            runtime
                .runtime_workbook_mut(source_workbook)
                .expect("source runtime workbook")
                .loaded
                .package
                .remove_part("xl/drawings/userShapes1.xml")
        );
        let source_sheet = expect_object_handle(
            runtime
                .dispatch_get(source_workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("source Workbook.Worksheets(1)"),
        );
        let target_workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open target workbook");
        let target_sheet = expect_object_handle(
            runtime
                .dispatch_get(target_workbook.0, "Worksheets", &[OmValue::Number(1.0)])
                .expect("target Workbook.Worksheets(1)"),
        );

        let error = runtime
            .dispatch_invoke(source_sheet, "Copy", &[OmValue::Object(target_sheet)])
            .expect_err("dangling chart relationship graph should fail atomically");
        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(
            error
                .message
                .contains("opaque relationship target part is missing")
        );
        let target_runtime = runtime
            .runtime_workbook(target_workbook)
            .expect("target workbook after rejected copy");
        assert_eq!(target_runtime.loaded.state.worksheets.len(), 1);
        assert!(target_runtime.loaded.pending_chart_relationship_graphs.is_empty());
        assert!(!target_runtime.prompt_dirty);
        assert!(
            !runtime
                .runtime_workbook(source_workbook)
                .unwrap()
                .prompt_dirty
        );
    }

    #[test]
    fn worksheet_copy_preserves_embedded_chart_support_parts_for_placement_copy() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_with_embedded_chart_support_parts_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open embedded chart support workbook");
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let application = runtime.root_application();
        let sheet1 = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("Worksheets.Item(1)"),
        );
        let source_range = expect_object_handle(
            runtime
                .dispatch_invoke(sheet1, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Sheet1.Range(A1) before embedded chart Worksheet.Copy"),
        );
        runtime
            .dispatch_set(
                source_range,
                "Value",
                OmValue::Text("embedded copy needle".to_string()),
                &[],
            )
            .expect("seed Range.Find value before embedded chart Worksheet.Copy");
        runtime
            .dispatch_invoke(source_range, "Copy", &[])
            .expect("Range.Copy before embedded chart Worksheet.Copy");
        runtime
            .dispatch_invoke(
                source_range,
                "Find",
                &[OmValue::Text("embedded copy needle".to_string())],
            )
            .expect("Range.Find before embedded chart Worksheet.Copy");
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(application, "CutCopyMode", &[])
                    .expect("Application.CutCopyMode before embedded chart Worksheet.Copy")
            ),
            f64::from(super::XL_COPY)
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(sheet1, "Copy", &[OmValue::Missing, OmValue::Number(1.0)])
                .expect("Worksheet.Copy After:=1 on embedded chart sheet"),
            OmValue::Empty
        ));
        assert!(!expect_bool(
            runtime
                .dispatch_get(application, "CutCopyMode", &[])
                .expect("Application.CutCopyMode after embedded chart Worksheet.Copy")
        ));
        assert_eq!(
            runtime
                .dispatch_invoke(source_range, "FindNext", &[])
                .expect_err(
                    "Range.FindNext should require a new Find after embedded chart Worksheet.Copy",
                )
                .code,
            OmErrorCode::InvalidState
        );

        let saved = runtime
            .save_workbook(
                workbook,
                SaveWorkbookSpec {
                    format: FileFormat::Xlsx,
                    profile: ExcelProfile::Excel365,
                    lossless: true,
                },
            )
            .expect("save copied embedded chart workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let copied_chart_rels = String::from_utf8(
            saved_package
                .part("xl/charts/_rels/chart2.xml.rels")
                .expect("copied chart relationships")
                .bytes
                .clone(),
        )
        .expect("copied chart relationships utf8");
        assert!(copied_chart_rels.contains(
            r#"Type="http://schemas.microsoft.com/office/2011/relationships/chartStyle""#
        ));
        assert!(copied_chart_rels.contains(
            r#"Type="http://schemas.microsoft.com/office/2011/relationships/chartColorStyle""#
        ));
        assert!(
            saved_package
                .part("xl/charts/style2.xml")
                .map(|part| String::from_utf8_lossy(&part.bytes).contains(r#"id="404""#))
                .unwrap_or(false),
            "copied worksheet chart style support part should be copied"
        );
        assert!(
            saved_package
                .part("xl/charts/colors2.xml")
                .map(|part| String::from_utf8_lossy(&part.bytes).contains(r#"id="404""#))
                .unwrap_or(false),
            "copied worksheet chart color support part should be copied"
        );

        let mut reopened_runtime = ExcelRuntime::new();
        let reopened_workbook = reopened_runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: saved,
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("reopen copied embedded chart workbook");
        let reopened_worksheets = expect_object_handle(
            reopened_runtime
                .dispatch_get(reopened_workbook.0, "Worksheets", &[])
                .expect("reopened Workbook.Worksheets"),
        );
        let copied_sheet = expect_object_handle(
            reopened_runtime
                .dispatch_invoke(reopened_worksheets, "Item", &[OmValue::Number(2.0)])
                .expect("reopened copied worksheet"),
        );
        let copied_chart_objects = expect_object_handle(
            reopened_runtime
                .dispatch_get(copied_sheet, "ChartObjects", &[])
                .expect("reopened copied ChartObjects"),
        );
        assert_eq!(
            expect_number(
                reopened_runtime
                    .dispatch_get(copied_chart_objects, "Count", &[])
                    .expect("reopened copied ChartObjects.Count")
            ),
            1.0
        );
    }

